<?php
if (!defined('ABSPATH')) { exit; }
/** Adapted from the user-supplied StraySafe Shop v0.11.6. Storage keys are retained for migration. */
final class Rescue_Shop_Engine {
 const POST_TYPE='ssshop_product', TAXONOMY='ssshop_category', ORDER_TYPE='ssshop_order', CART_COOKIE='ssshop_cart';
 public static function init(){
  add_action('init',[__CLASS__,'register_content']); add_action('add_meta_boxes',[__CLASS__,'meta_boxes']); add_action('save_post_'.self::POST_TYPE,[__CLASS__,'save_product']);
  add_shortcode('straysafe_shop',[__CLASS__,'catalogue']); add_shortcode('straysafe_shop_product',[__CLASS__,'product_shortcode']); add_shortcode('straysafe_shop_basket',[__CLASS__,'basket_shortcode']);
  add_action('wp_enqueue_scripts',[__CLASS__,'conditionally_assets']);  add_action('admin_init',[__CLASS__,'register_settings']); add_action('admin_post_ssshop_test_email',[__CLASS__,'test_email']);
  add_filter('manage_'.self::POST_TYPE.'_posts_columns',[__CLASS__,'columns']); add_action('manage_'.self::POST_TYPE.'_posts_custom_column',[__CLASS__,'column_value'],10,2);
  add_filter('manage_'.self::ORDER_TYPE.'_posts_columns',[__CLASS__,'order_columns']); add_action('manage_'.self::ORDER_TYPE.'_posts_custom_column',[__CLASS__,'order_column_value'],10,2);
  foreach(['add_cart','update_cart','edit_cart','checkout','group_contribution','group_asset','manage_design','media_search','media_import','upload_card_image'] as $a){add_action('wp_ajax_ssshop_'.$a,[__CLASS__,'ajax_'.$a]);add_action('wp_ajax_nopriv_ssshop_'.$a,[__CLASS__,'ajax_'.$a]);}
  add_action('rest_api_init',function(){register_rest_route('straysafe-shop/v1','/stripe/webhook',['methods'=>'POST','callback'=>[__CLASS__,'stripe_webhook'],'permission_callback'=>'__return_true']);});
  add_action('template_redirect',[__CLASS__,'private_card_asset'],0); add_action('template_redirect',[__CLASS__,'sender_card_manage']); add_action('template_redirect',[__CLASS__,'block_public_product_routes'],1); add_action('template_redirect',[__CLASS__,'checkout_return']); add_action('template_redirect',[__CLASS__,'group_contribution']); add_action('template_redirect',[__CLASS__,'recipient_card']);
  add_action('ssshop_delivery_tick',[__CLASS__,'process_due_deliveries']);
  add_action('wp_ajax_ssshop_order_status',[__CLASS__,'ajax_order_status']); add_action('wp_ajax_nopriv_ssshop_order_status',[__CLASS__,'ajax_order_status']);
  add_action('add_meta_boxes_'.self::ORDER_TYPE,[__CLASS__,'order_meta_box']); add_action('admin_post_ssshop_send_card_now',[__CLASS__,'admin_send_card_now']); add_action('admin_post_ssshop_update_card',[__CLASS__,'admin_update_card']); add_action('admin_post_ssshop_resend_confirmation',[__CLASS__,'admin_resend_confirmation']); add_action('admin_notices',[__CLASS__,'delivery_admin_notice']);
 }
 private static function admin_capabilities() {
  return array_fill_keys(['edit_post','read_post','delete_post','edit_posts','edit_others_posts','publish_posts','read_private_posts','delete_posts','delete_private_posts','delete_published_posts','delete_others_posts','edit_private_posts','edit_published_posts','create_posts'], 'manage_options');
 }
 private static function default_no_reply() {
  $host=wp_parse_url(home_url('/'),PHP_URL_HOST);$address=sanitize_email('no-reply@'.preg_replace('/^www\./','',(string)$host));return is_email($address)?$address:get_option('admin_email');
 }
 public static function conditionally_assets() {
  if(isset($_GET['ssshop_card'])||isset($_GET['ssshop_manage'])||isset($_GET['ssshop_group'])){self::assets();return;}
  if(!is_singular())return;$post=get_queried_object();if(!$post||empty($post->post_content))return;
  foreach(['rescue_shop','rescue_shop_product','rescue_shop_basket','straysafe_shop','straysafe_shop_product','straysafe_shop_basket'] as $tag)if(has_shortcode($post->post_content,$tag)){self::assets();return;}
 }

 private static function retained_asset_files(){global $wpdb;$values=$wpdb->get_col($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name LIKE %s",$wpdb->esc_like('ssshop_asset_').'%'));$files=[];foreach($values as $value){$meta=maybe_unserialize($value);if(is_array($meta)&&is_string($meta['file']??null))$files[$meta['file']]=true;}return $files;}
 public static function cleanup_card_assets(){
  if(get_transient('ssshop_asset_cleanup_recent'))return;set_transient('ssshop_asset_cleanup_recent',1,HOUR_IN_SECONDS);$retained=self::retained_asset_files();$dir=self::card_asset_dir();foreach(glob($dir.'/*')?:[] as $file){if(!is_file($file)||!preg_match('/\.(?:gif|png|jpe?g|webp)$/i',$file)||isset($retained[$file]))continue;if(filemtime($file)<time()-30*DAY_IN_SECONDS)wp_delete_file($file);}
 }
 private static function reserve_card_upload($bytes){
  self::cleanup_card_assets();$retained=self::retained_asset_files();$draft_bytes=0;foreach(glob(self::card_asset_dir().'/*')?:[] as $file)if(is_file($file)&&!isset($retained[$file])&&preg_match('/\.(?:gif|png|jpe?g|webp)$/i',$file))$draft_bytes+=filesize($file);
  if($draft_bytes+max(0,(int)$bytes)>100*MB_IN_BYTES)return new WP_Error('storage_full','Temporary card storage is full. Please contact the rescue.');
  $ip=is_string($_SERVER['REMOTE_ADDR']??null)?$_SERVER['REMOTE_ADDR']:'unknown';$ip_key='ssshop_upload_ip_'.hash_hmac('sha256',$ip,wp_salt('nonce'));$site_key='ssshop_upload_site';$ip_count=(int)get_transient($ip_key);$site_count=(int)get_transient($site_key);
  if($ip_count>=30||$site_count>=120)return new WP_Error('upload_limit','The upload limit has been reached. Please try again in an hour.');set_transient($ip_key,$ip_count+1,HOUR_IN_SECONDS);set_transient($site_key,$site_count+1,HOUR_IN_SECONDS);return true;
 }
 private static function card_asset_dir(){ $u=wp_upload_dir();$dir=trailingslashit($u['basedir']).'straysafe-shop-private';if(!is_dir($dir))wp_mkdir_p($dir);if(is_dir($dir)){@file_put_contents($dir.'/.htaccess',"Require all denied\nDeny from all\nOptions -Indexes\n");@file_put_contents($dir.'/index.php',"<?php http_response_code(404); exit;\n");}return $dir;}
 private static function card_asset_key($token){return 'ssshop_asset_'.hash('sha256',$token);}
 private static function card_asset_meta($token){$meta=get_option(self::card_asset_key($token),false);return is_array($meta)?$meta:get_transient(self::card_asset_key($token));}
 private static function persist_card_assets($pages){foreach(is_array($pages)?$pages:[] as $page)foreach(is_array($page['blocks']??null)?$page['blocks']:[] as $block){$token=$block['asset_token']??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/',$token))continue;$meta=self::card_asset_meta($token);if(is_array($meta))add_option(self::card_asset_key($token),$meta,'','no');}}
 private static function card_asset_url($token){return add_query_arg('ssshop_asset',rawurlencode($token),home_url('/'));}
 public static function private_card_asset(){if(empty($_GET['ssshop_asset']))return;$token=sanitize_text_field(wp_unslash($_GET['ssshop_asset']));if(!preg_match('/^[a-f0-9]{64}$/',$token)){status_header(404);exit;}$meta=self::card_asset_meta($token);if(!is_array($meta)||empty($meta['file'])||empty($meta['mime'])){status_header(404);nocache_headers();header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet',true);exit;}$base=realpath(self::card_asset_dir());$file=realpath($meta['file']);if(!$base||!$file||strpos($file,$base.DIRECTORY_SEPARATOR)!==0||!is_file($file)){status_header(404);exit;}$mime=(string)$meta['mime'];if(!in_array($mime,['image/jpeg','image/png','image/webp','image/gif'],true)){status_header(403);exit;}status_header(200);header('Content-Type: '.$mime);header('Content-Length: '.filesize($file));header('Cache-Control: private, max-age=3600, no-store');header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet',true);header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');readfile($file);exit;}
 public static function block_public_product_routes(){if(is_singular(self::POST_TYPE)||is_tax(self::TAXONOMY)){wp_safe_redirect(home_url('/shop/'),301);exit;}}
 public static function register_content(){
  register_post_type(self::POST_TYPE,['labels'=>['name'=>'Shop Products','singular_name'=>'Product','add_new_item'=>'Add Product','edit_item'=>'Edit Product','menu_name'=>'Products'],'public'=>false,'publicly_queryable'=>false,'exclude_from_search'=>true,'show_ui'=>true,'show_in_rest'=>true,'has_archive'=>false,'rewrite'=>false,'query_var'=>false,'supports'=>['title','editor','thumbnail','excerpt','revisions'],'capability_type'=>'post','map_meta_cap'=>false,'capabilities'=>self::admin_capabilities(),'show_in_menu'=>false]);
  register_taxonomy(self::TAXONOMY,self::POST_TYPE,['labels'=>['name'=>'Product Categories','singular_name'=>'Product Category'],'public'=>false,'publicly_queryable'=>false,'show_ui'=>true,'show_in_rest'=>true,'hierarchical'=>true,'capabilities'=>['manage_terms'=>'manage_options','edit_terms'=>'manage_options','delete_terms'=>'manage_options','assign_terms'=>'manage_options'],'rewrite'=>false,'query_var'=>false]);
  register_post_type(self::ORDER_TYPE,['labels'=>['name'=>'Orders','singular_name'=>'Order','menu_name'=>'Orders'],'public'=>false,'show_ui'=>true,'show_in_menu'=>false,'supports'=>['title'],'capability_type'=>'post','map_meta_cap'=>false,'capabilities'=>self::admin_capabilities()]);
 }
 public static function activate(){self::register_content();flush_rewrite_rules();if(!wp_next_scheduled('ssshop_delivery_tick'))wp_schedule_event(time()+300,'hourly','ssshop_delivery_tick');add_option('ssshop_intro','Every purchase helps cats in need.');add_option('ssshop_sustainability','Choose digital where available for a paper-free way to send something special while supporting cats in need.');add_option('ssshop_stripe_mode','test');}
 public static function deactivate(){$t=wp_next_scheduled('ssshop_delivery_tick');if($t)wp_unschedule_event($t,'ssshop_delivery_tick');flush_rewrite_rules();}

 public static function dashboard(){if(!current_user_can('manage_options'))wp_die('Access denied.');$pc=wp_count_posts(self::POST_TYPE);$oc=wp_count_posts(self::ORDER_TYPE);$stripe=(bool)self::stripe_secret();$mode=get_option('ssshop_stripe_mode','test');$wh=self::webhook_secret();$paid=get_posts(['post_type'=>self::ORDER_TYPE,'post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_ssshop_order_status','meta_value'=>'paid','fields'=>'ids']);echo '<div class="wrap"><h1>Rescue Shop</h1><p>Version '.esc_html(RPS_SHOP_VERSION).'</p><div style="display:flex;gap:14px;flex-wrap:wrap;margin:20px 0">';foreach([['Published products',(int)($pc->publish??0)],['Orders',(int)($oc->publish??0)],['Paid orders',count($paid)]] as $box)echo '<div style="background:#fff;border:1px solid #ddd;border-radius:8px;padding:18px 24px;min-width:150px"><strong style="font-size:26px;display:block">'.esc_html((string)$box[1]).'</strong>'.esc_html($box[0]).'</div>';echo '</div><h2>Shop status</h2><table class="widefat striped" style="max-width:760px"><tbody><tr><td><strong>Stripe mode</strong></td><td>'.esc_html(ucfirst($mode)).'</td></tr><tr><td><strong>Stripe secret key</strong></td><td>'.($stripe?'✓ Configured':'✕ Not configured').'</td></tr><tr><td><strong>Webhook signing secret</strong></td><td>'.($wh?'✓ Configured':'✕ Not configured').'</td></tr><tr><td><strong>Storefront shortcode</strong></td><td><code>[straysafe_shop]</code></td></tr><tr><td><strong>Basket shortcode</strong></td><td><code>[straysafe_shop_basket]</code></td></tr></tbody></table>';if($mode==='live')echo '<div class="notice notice-warning inline"><p><strong>Live mode is enabled.</strong> Real payments can be processed.</p></div>';elseif($stripe&&$wh)echo '<div class="notice notice-success inline"><p>Stripe test checkout and webhook verification are configured.</p></div>';else echo '<div class="notice notice-info inline"><p>Complete the Stripe test configuration in Settings before testing payments.</p></div>';echo '</div>';}
 public static function register_settings(){
  foreach(['ssshop_shop_title','ssshop_intro','ssshop_sustainability'] as $k)register_setting('ssshop_shop_settings',$k,['type'=>'string','sanitize_callback'=>'sanitize_text_field']);
  register_setting('ssshop_payment_settings','ssshop_stripe_mode',['type'=>'string','sanitize_callback'=>function($v){return $v==='live'?'live':'test';}]);
  foreach(['ssshop_stripe_test_secret','ssshop_stripe_test_webhook','ssshop_stripe_live_secret','ssshop_stripe_live_webhook'] as $k){register_setting('ssshop_payment_settings',$k,['type'=>'string','sanitize_callback'=>function($v)use($k){$v=sanitize_text_field($v);return $v!==''?$v:get_option($k,'');}]);}
  foreach(['ssshop_email_from_name','ssshop_email_subject','ssshop_email_heading'] as $k)register_setting('ssshop_email_settings',$k,['sanitize_callback'=>'sanitize_text_field']);
  foreach(['ssshop_email_from_address','ssshop_email_reply_to'] as $k)register_setting('ssshop_email_settings',$k,['sanitize_callback'=>'sanitize_email']);
  register_setting('ssshop_email_settings','ssshop_email_intro',['sanitize_callback'=>'sanitize_textarea_field']);
  foreach(['ssshop_order_subject','ssshop_order_heading'] as $k)register_setting('ssshop_email_settings',$k,['sanitize_callback'=>'sanitize_text_field']);
  foreach(['ssshop_order_body'] as $k)register_setting('ssshop_email_settings',$k,['sanitize_callback'=>'sanitize_textarea_field']);
  register_setting('ssshop_shop_settings','ssshop_giphy_key',['sanitize_callback'=>function($v){$v=sanitize_text_field($v);return $v!==''?$v:get_option('ssshop_giphy_key','');}]);
  register_setting('ssshop_email_settings','ssshop_email_transport',['sanitize_callback'=>function($v){return $v==='smtp'?'smtp':'wordpress';}]);
  foreach(['ssshop_smtp_host','ssshop_smtp_username'] as $k)register_setting('ssshop_email_settings',$k,['sanitize_callback'=>'sanitize_text_field']);
  register_setting('ssshop_email_settings','ssshop_smtp_port',['sanitize_callback'=>'absint']);
  register_setting('ssshop_email_settings','ssshop_smtp_encryption',['sanitize_callback'=>'sanitize_key']);
  register_setting('ssshop_email_settings','ssshop_smtp_password',['sanitize_callback'=>function($v){return $v!==''?(string)$v:get_option('ssshop_smtp_password','');}]);
 }
 public static function settings_page(){if(!current_user_can('manage_options'))wp_die('Access denied.');$tab=isset($_GET['shop_tab'])?sanitize_key(wp_unslash($_GET['shop_tab'])):'shop';$mode=get_option('ssshop_stripe_mode','test');echo '<div class="wrap"><h1>Rescue Shop Settings</h1>';settings_errors();if(isset($_GET['ssshop_email_test']))echo '<div class="notice '.($_GET['ssshop_email_test']==='sent'?'notice-success':'notice-error').' is-dismissible"><p>'.($_GET['ssshop_email_test']==='sent'?'Test email sent successfully.':'Test email could not be sent. Check the settings and your server/provider mail logs.').'</p></div>';echo '<nav class="nav-tab-wrapper"><a class="nav-tab '.($tab==='shop'?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page=plugin-ui-suite&tab=shop&shop_section=settings&shop_tab=shop')).'">Shop</a><a class="nav-tab '.($tab==='payments'?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page=plugin-ui-suite&tab=shop&shop_section=settings&shop_tab=payments')).'">Payments</a><a class="nav-tab '.($tab==='email'?'nav-tab-active':'').'" href="'.esc_url(admin_url('admin.php?page=plugin-ui-suite&tab=shop&shop_section=settings&shop_tab=email')).'">Email</a></nav><form method="post" action="options.php">';$settings_group=$tab==='email'?'ssshop_email_settings':($tab==='payments'?'ssshop_payment_settings':'ssshop_shop_settings');settings_fields($settings_group);echo '<input type="hidden" name="_wp_http_referer" value="'.esc_attr(admin_url('admin.php?page=plugin-ui-suite&tab=shop&shop_section=settings&shop_tab='.$tab.'&settings-updated=true')).'">';if($tab==='email'){echo '<h2>Email delivery</h2><p>Configure the sending method once, then set reusable templates by fulfilment type. Products automatically use the template for their format and fulfilment type.</p><table class="form-table"><tr><th>Delivery method</th><td><select name="ssshop_email_transport"><option value="wordpress" '.selected(get_option('ssshop_email_transport','wordpress'),'wordpress',false).'>WordPress mail</option><option value="smtp" '.selected(get_option('ssshop_email_transport','wordpress'),'smtp',false).'>SMTP</option></select></td></tr><tr><th>From name</th><td><input class="regular-text" name="ssshop_email_from_name" value="'.esc_attr(get_option('ssshop_email_from_name', get_bloginfo('name'))).'"></td></tr><tr><th>From email</th><td><input class="regular-text" type="email" name="ssshop_email_from_address" value="'.esc_attr(get_option('ssshop_email_from_address',get_option('admin_email'))).'"></td></tr><tr><th>Default reply-to</th><td><input class="regular-text" type="email" name="ssshop_email_reply_to" value="'.esc_attr(get_option('ssshop_email_reply_to',get_option('admin_email'))).'"><p class="description">E-cards use the buyer address only when the buyer explicitly allows replies; otherwise they use the rescue’s configured reply-to address.</p></td></tr></table><hr><h2>Buyer order confirmation</h2><p>Sent once per paid order, regardless of how many fulfilment types are in the basket.</p><table class="form-table"><tr><th>Subject</th><td><input class="large-text" name="ssshop_order_subject" value="'.esc_attr(get_option('ssshop_order_subject','Rescue Shop order #{order_number} confirmed')).'"></td></tr><tr><th>Heading</th><td><input class="large-text" name="ssshop_order_heading" value="'.esc_attr(get_option('ssshop_order_heading','Thank you for your order')).'"></td></tr><tr><th>Body</th><td><textarea class="large-text" rows="5" name="ssshop_order_body">'.esc_textarea(get_option('ssshop_order_body','Your Rescue Shop order #{order_number} is confirmed and paid.\n\n{products}\n\nTotal: {total}\n\nStripe may send a separate payment receipt.')).'</textarea><p class="description">Placeholders: <code>{order_number}</code> <code>{products}</code> <code>{total}</code> <code>{customer_email}</code></p></td></tr></table><hr><h2>Interactive e-card</h2><p>Sent to each e-card recipient on its chosen delivery date.</p><table class="form-table"><tr><th>Subject</th><td><input class="large-text" name="ssshop_email_subject" value="'.esc_attr(get_option('ssshop_email_subject','You have a rescue e-card from {sender_name}!')).'"></td></tr><tr><th>Heading</th><td><input class="large-text" name="ssshop_email_heading" value="'.esc_attr(get_option('ssshop_email_heading','You have a rescue e-card!')).'"></td></tr><tr><th>Body / intro</th><td><textarea class="large-text" rows="4" name="ssshop_email_intro">'.esc_textarea(get_option('ssshop_email_intro','{sender_name} has sent you something special. Open your card using the button below.')).'</textarea><p class="description">Placeholders: <code>{sender_name}</code> <code>{recipient_name}</code> <code>{product}</code> <code>{delivery_date}</code>. The secure card button is added automatically.</p></td></tr></table><h2>SMTP</h2><p>Only used when Delivery method is set to SMTP.</p><table class="form-table"><tr><th>Host</th><td><input class="regular-text" name="ssshop_smtp_host" value="'.esc_attr(get_option('ssshop_smtp_host','')).'"></td></tr><tr><th>Port</th><td><input type="number" name="ssshop_smtp_port" value="'.esc_attr(get_option('ssshop_smtp_port',587)).'"></td></tr><tr><th>Encryption</th><td><select name="ssshop_smtp_encryption"><option value="tls" '.selected(get_option('ssshop_smtp_encryption','tls'),'tls',false).'>TLS</option><option value="ssl" '.selected(get_option('ssshop_smtp_encryption','tls'),'ssl',false).'>SSL</option><option value="none" '.selected(get_option('ssshop_smtp_encryption','tls'),'none',false).'>None</option></select></td></tr><tr><th>Username</th><td><input class="regular-text" name="ssshop_smtp_username" value="'.esc_attr(get_option('ssshop_smtp_username','')).'"></td></tr><tr><th>Password</th><td><input class="regular-text" type="password" autocomplete="new-password" name="ssshop_smtp_password" value="" placeholder="'.(get_option('ssshop_smtp_password','')?'Configured - enter a new value to replace':'Not configured').'"></td></tr></table>';submit_button('Save email settings');echo '</form><hr><h2>Test email</h2><p>Send a test using the configuration above after saving it.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ssshop_test_email">';wp_nonce_field('ssshop_test_email');echo '<input required type="email" class="regular-text" aria-label="Test email recipient" name="test_email" value="'.esc_attr(wp_get_current_user()->user_email).'"> ';submit_button('Send test email','secondary','submit',false);echo '</form>';}elseif($tab==='payments'){echo '<h2>Stripe</h2><table class="form-table"><tr><th>Stripe mode</th><td><select name="ssshop_stripe_mode"><option value="test" '.selected($mode,'test',false).'>Test</option><option value="live" '.selected($mode,'live',false).'>Live</option></select></td></tr><tr><th>Test secret key</th><td><input class="regular-text" type="password" autocomplete="off" name="ssshop_stripe_test_secret" value="" placeholder="'.(get_option('ssshop_stripe_test_secret','')?'Configured - enter a new value to replace':'Not configured').'"></td></tr><tr><th>Test webhook signing secret</th><td><input class="regular-text" type="password" autocomplete="off" name="ssshop_stripe_test_webhook" value="" placeholder="'.(get_option('ssshop_stripe_test_webhook','')?'Configured - enter a new value to replace':'Not configured').'"><p class="description">Webhook URL: <code>'.esc_html(rest_url('straysafe-shop/v1/stripe/webhook')).'</code></p></td></tr><tr><th>Live secret key</th><td><input class="regular-text" type="password" autocomplete="off" name="ssshop_stripe_live_secret" value="" placeholder="'.(get_option('ssshop_stripe_live_secret','')?'Configured - enter a new value to replace':'Not configured').'"></td></tr><tr><th>Live webhook signing secret</th><td><input class="regular-text" type="password" autocomplete="off" name="ssshop_stripe_live_webhook" value="" placeholder="'.(get_option('ssshop_stripe_live_webhook','')?'Configured - enter a new value to replace':'Not configured').'"></td></tr></table>';submit_button('Save payment settings');echo '</form>';}else{echo '<h2>Storefront</h2><table class="form-table"><tr><th>Shop title</th><td><input class="regular-text" name="ssshop_shop_title" value="'.esc_attr(get_option('ssshop_shop_title','Rescue Shop')).'"></td></tr><tr><th>Shop introduction</th><td><input class="regular-text" name="ssshop_intro" value="'.esc_attr(get_option('ssshop_intro','')).'"></td></tr><tr><th>Digital sustainability message</th><td><textarea class="large-text" rows="3" name="ssshop_sustainability">'.esc_textarea(get_option('ssshop_sustainability','')).'</textarea></td></tr></table><h2>Card media library</h2><table class="form-table"><tr><th>GIPHY API key</th><td><input class="regular-text" type="password" autocomplete="off" name="ssshop_giphy_key" value="" placeholder="'.(get_option('ssshop_giphy_key','')?'Configured - enter a new value to replace':'Not configured').'"><p class="description">Enables GIF search in card editors. Search results include GIPHY attribution.</p></td></tr><tr><th>Image search</th><td><p class="description">The image-search provider slot is ready, but web image search stays disabled until a provider that permits importing selected images into protected card storage is configured. Customer uploads remain available.</p></td></tr></table>';submit_button('Save shop settings');echo '</form>';}echo '</div>';}
 public static function configure_mailer($m){if(get_option('ssshop_email_transport','wordpress')!=='smtp')return;$host=trim(get_option('ssshop_smtp_host',''));if(!$host)return;$m->isSMTP();$m->Host=$host;$m->Port=absint(get_option('ssshop_smtp_port',587));$user=get_option('ssshop_smtp_username','');$pass=get_option('ssshop_smtp_password','');$m->SMTPAuth=($user!==''||$pass!=='');if($m->SMTPAuth){$m->Username=$user;$m->Password=$pass;}$enc=get_option('ssshop_smtp_encryption','tls');$m->SMTPSecure=$enc==='none'?'':$enc;$m->SMTPAutoTLS=$enc!=='none';}
 private static function send_shop_email($to,$subject,$html,$reply_override='') {
  $headers=['Content-Type: text/html; charset=UTF-8'];$from=get_option('ssshop_email_from_address',get_option('admin_email'));$name=get_option('ssshop_email_from_name',get_bloginfo('name'));$reply=is_email($reply_override)?$reply_override:get_option('ssshop_email_reply_to',get_option('admin_email'));
  if(is_email($from))$headers[]='From: '.sanitize_text_field($name).' <'.$from.'>';if(is_email($reply))$headers[]='Reply-To: '.$reply;
  // wp_mail reuses a global mailer: isolate shop SMTP configuration per message.
  $previous=$GLOBALS['phpmailer']??null;
  if(is_object($previous))$GLOBALS['phpmailer']=clone $previous;
  add_action('phpmailer_init',[__CLASS__,'configure_mailer']);
  try{return wp_mail($to,$subject,$html,$headers);}
  finally{remove_action('phpmailer_init',[__CLASS__,'configure_mailer']);if($previous!==null)$GLOBALS['phpmailer']=$previous;else unset($GLOBALS['phpmailer']);}
 }

 public static function test_email(){if(!current_user_can('manage_options'))wp_die('Access denied.');check_admin_referer('ssshop_test_email');$to=sanitize_email($_POST['test_email']??'');$body='<div style="font-family:Arial,sans-serif;max-width:600px;margin:30px auto;padding:28px;border:1px solid #eee;border-radius:12px"><h1 style="color:#48105f">Email delivery is working</h1><p>This test was sent by Rescue Shop using your current email configuration.</p></div>';$ok=$to&&self::send_shop_email($to,'Rescue Shop test email',$body);wp_safe_redirect(admin_url('admin.php?page=plugin-ui-suite&tab=shop&shop_section=settings&shop_tab=email&ssshop_email_test='.($ok?'sent':'failed')));exit;}
 public static function meta_boxes(){add_meta_box('ssshop_product_details','Product Details',[__CLASS__,'product_fields'],self::POST_TYPE,'normal','high');add_meta_box('ssshop_order_details','Order Details',[__CLASS__,'order_fields'],self::ORDER_TYPE,'normal','high');}
 public static function product_fields($post){wp_nonce_field('ssshop_save_product','ssshop_nonce');$price=get_post_meta($post->ID,'_ssshop_price_pence',true);$type=get_post_meta($post->ID,'_ssshop_type',true)?:'digital';$kind=get_post_meta($post->ID,'_ssshop_digital_kind',true)?:'ecard';$visibility=get_post_meta($post->ID,'_ssshop_visibility',true)?:'catalogue';$featured=get_post_meta($post->ID,'_ssshop_featured',true)==='yes';echo '<p><label><strong>Price (£)</strong></label><br><input type="number" min="0" max="999999" step="0.01" aria-label="Price in pounds" name="ssshop_price" value="'.esc_attr($price===''?'3.50':number_format(((int)$price)/100,2,'.','')).'" required></p><p><label><strong>Product format</strong></label><br><select aria-label="Product format" name="ssshop_type">';foreach(['digital'=>'Digital','physical'=>'Physical (future)','both'=>'Digital and physical (future)'] as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($type,$k,false).'>'.esc_html($v).'</option>';echo '</select></p><p><label><strong>Digital fulfilment type</strong></label><br><select aria-label="Digital fulfilment type" name="ssshop_digital_kind">';foreach(['ecard'=>'Interactive e-card','download'=>'Secure download (future; no checkout)','other'=>'Other digital item (future; no checkout)'] as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($kind,$k,false).'>'.esc_html($v).'</option>';echo '</select></p><p><label><strong>Catalogue visibility</strong></label><br><select aria-label="Product visibility" name="ssshop_visibility"><option value="catalogue" '.selected($visibility,'catalogue',false).'>Visible in catalogue</option><option value="hidden" '.selected($visibility,'hidden',false).'>Hidden from catalogue</option></select></p><p><label><input type="checkbox" name="ssshop_featured" value="yes" '.checked($featured,true,false).'> Featured product</label></p>';}
 public static function save_product($id){if(!isset($_POST['ssshop_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ssshop_nonce'])),'ssshop_save_product')||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)||!current_user_can('edit_post',$id))return;$raw=sanitize_text_field(wp_unslash($_POST['ssshop_price']??''));if(preg_match('/^\d{1,6}(?:\.\d{1,2})?$/',$raw)){$p=explode('.',$raw);update_post_meta($id,'_ssshop_price_pence',((int)$p[0])*100+(int)str_pad($p[1]??'',2,'0'));}foreach(['type'=>['digital','physical','both'],'digital_kind'=>['ecard','download','other'],'visibility'=>['catalogue','hidden']] as $f=>$allowed){$v=sanitize_key(wp_unslash($_POST['ssshop_'.$f]??''));if(in_array($v,$allowed,true))update_post_meta($id,'_ssshop_'.$f,$v);}update_post_meta($id,'_ssshop_featured',isset($_POST['ssshop_featured'])?'yes':'no');update_post_meta($id,'_ssshop_personalised',isset($_POST['ssshop_personalised'])?'yes':'no');}
 public static function order_fields($post){$status=get_post_meta($post->ID,'_ssshop_order_status',true)?:'pending';$total=(int)get_post_meta($post->ID,'_ssshop_order_total',true);$email=get_post_meta($post->ID,'_ssshop_customer_email',true);$items=get_post_meta($post->ID,'_ssshop_order_items',true);echo '<p><strong>Status:</strong> '.esc_html(ucwords(str_replace('_',' ',$status))).'</p><p><strong>Total:</strong> £'.esc_html(number_format($total/100,2)).'</p><p><strong>Customer:</strong> '.esc_html($email?:'Awaiting Stripe').'</p>';if(is_array($items)){echo '<ul>';foreach($items as $i)echo '<li>'.esc_html($i['name'].' × '.$i['quantity'].' — £'.number_format(($i['unit_amount']*$i['quantity'])/100,2)).'</li>';echo '</ul>';}echo '<p><small>Stripe session: '.esc_html(get_post_meta($post->ID,'_ssshop_stripe_session',true)).'</small></p>';}
 public static function assets(){$css=RPS_SHOP_PATH.'assets/shop.css';$js=RPS_SHOP_PATH.'assets/shop.js';$css_v=is_file($css)?RPS_SHOP_VERSION.'.'.filemtime($css):RPS_SHOP_VERSION;$js_v=is_file($js)?RPS_SHOP_VERSION.'.'.filemtime($js):RPS_SHOP_VERSION;wp_enqueue_style('ssshop-style',RPS_SHOP_URL.'assets/shop.css',[],$css_v);wp_enqueue_script('rescue-plugin-suite-shared-modal',PLUGIN_SUITE_URL.'assets/js/shared-modal.js',[],PLUGIN_SUITE_VERSION,true);wp_enqueue_script('ssshop-script',RPS_SHOP_URL.'assets/shop.js',['rescue-plugin-suite-shared-modal'],$js_v,true);wp_localize_script('ssshop-script','RescueShop',['ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('ssshop_cart')]);}
 private static function cart() {
  $cookie=$_COOKIE[self::CART_COOKIE]??'';
  if(!is_string($cookie)||strlen($cookie)>65536)return [];
  $cookie=wp_unslash($cookie);if(preg_match('/^rps1_[a-f0-9]{64}$/',$cookie)){$data=get_transient('ssshop_cart_'.hash('sha256',$cookie));}else{$decoded=base64_decode($cookie,true);$data=$decoded!==false?json_decode($decoded,true,24):null;}
  if(!is_array($data))return [];
  $out=[];
  foreach(array_slice($data,0,30) as $line){
   if(!is_array($line))continue;
   $id=absint($line['product_id']??0);if(!$id)continue;
   $line_id=is_scalar($line['line_id']??null)?sanitize_key((string)$line['line_id']):'';
   $out[]=['line_id'=>$line_id?:str_replace('-','',wp_generate_uuid4()),'product_id'=>$id,'quantity'=>get_post_meta($id,'_ssshop_digital_kind',true)==='ecard'?1:max(1,min(20,absint($line['quantity']??1))),'personalisation'=>is_array($line['personalisation']??null)?$line['personalisation']:[]];
  }
  return $out;
 }

 private static function save_cart($cart) {
  $current=$_COOKIE[self::CART_COOKIE]??'';$token=is_string($current)&&preg_match('/^rps1_[a-f0-9]{64}$/',$current)?$current:'rps1_'.bin2hex(random_bytes(32));
  $key='ssshop_cart_'.hash('sha256',$token);
  if($cart)set_transient($key,array_slice(array_values($cart),0,30),30*DAY_IN_SECONDS);else delete_transient($key);
  setcookie(self::CART_COOKIE,$cart?$token:'',['expires'=>$cart?time()+30*DAY_IN_SECONDS:time()-DAY_IN_SECONDS,'path'=>COOKIEPATH?:'/','domain'=>COOKIE_DOMAIN,'secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax']);
  $_COOKIE[self::CART_COOKIE]=$cart?$token:'';
 }

 private static function purchasable($id){return get_post_type($id)===self::POST_TYPE&&get_post_status($id)==='publish'&&get_post_meta($id,'_ssshop_visibility',true)!=='hidden'&&in_array(get_post_meta($id,'_ssshop_type',true),['','digital'],true)&&get_post_meta($id,'_ssshop_digital_kind',true)==='ecard';}
 private static function cart_items($cart=null){$cart=$cart??self::cart();$items=[];foreach($cart as $line){$id=absint($line['product_id']??0);if(self::purchasable($id)){$p=(int)get_post_meta($id,'_ssshop_price_pence',true);if($p>0)$items[]=['line_id'=>$line['line_id'],'product_id'=>$id,'name'=>get_the_title($id),'quantity'=>$line['quantity'],'unit_amount'=>$p,'digital_kind'=>get_post_meta($id,'_ssshop_digital_kind',true)?:'other','card_reveal'=>sanitize_key(($line['personalisation']['card_reveal']??'')?:get_post_meta($id,'_ssshop_card_reveal',true)?:'gentle'),'personalisation'=>$line['personalisation']??[]];}}return$items;}
 private static function cart_summary($cart=null){$count=$total=0;foreach(self::cart_items($cart) as $i){$count+=$i['quantity'];$total+=$i['unit_amount']*$i['quantity'];}return['count'=>$count,'total'=>$total,'formatted'=>'£'.number_format($total/100,2)];}
 private static function clean_personalisation($id,$input=null) {
  if((get_post_meta($id,'_ssshop_digital_kind',true)?:'other')!=='ecard')return [];
  $input=$input===null?wp_unslash($_POST):(is_array($input)?$input:[]);
  $text=static function($key,$default='')use($input){return is_scalar($input[$key]??null)?sanitize_text_field((string)$input[$key]):$default;};
  $recipient=$text('recipient_name');$email=sanitize_email($text('recipient_email'));$sender=$text('sender_name');
  $to_prefix=$text('to_prefix','To');$from_prefix=$text('from_prefix','From');
  $message=is_scalar($input['message']??null)?sanitize_textarea_field((string)$input['message']):'';
  $decode=static function($raw){return is_array($raw)?$raw:(is_string($raw)?json_decode($raw,true,20):[]);};
  $raw_pages=$decode($input['message_pages']??[]);$message_pages=[];
  if(is_array($raw_pages))foreach(array_slice($raw_pages,0,6) as $mp){
   if(!is_scalar($mp))continue;$mp=sanitize_textarea_field((string)$mp);
   if(trim($mp)!=='')$message_pages[]=mb_substr($mp,0,1000);
  }
  if(!$message_pages&&trim($message)!=='')$message_pages=[mb_substr($message,0,1000)];
  $message=$message_pages[0]??'';$raw_canvas=$decode($input['card_pages']??[]);$card_pages=[];
  $scalar=static function($values,$key,$default=''){return is_scalar($values[$key]??null)?$values[$key]:$default;};
  if(is_array($raw_canvas))foreach(array_slice($raw_canvas,0,6) as $cp){
   if(!is_array($cp))continue;$blocks=[];
   foreach(array_slice(is_array($cp['blocks']??null)?$cp['blocks']:[],0,20) as $bl){
    if(!is_array($bl))continue;$type=sanitize_key((string)$scalar($bl,'type','text'));
    $geometry=['x'=>max(0,min(100,(float)$scalar($bl,'x',50))),'y'=>max(0,min(100,(float)$scalar($bl,'y',35)))];
    if($type==='sticker'){
     $sticker=(string)$scalar($bl,'sticker');
     if(!in_array($sticker,['🐾','🐱','😺','😻','❤️','💜','🎈','🎉','🎂','🎁','⭐','🌈','🌸','✨'],true))continue;
     $blocks[]=array_merge($geometry,['type'=>'sticker','sticker'=>$sticker,'w'=>max(8,min(50,(float)$scalar($bl,'w',18))),'h'=>max(8,min(50,(float)$scalar($bl,'h',18))),'rotation'=>max(-180,min(180,(float)$scalar($bl,'rotation',0)))]);continue;
    }
    if($type==='image'){
     $asset=sanitize_text_field((string)$scalar($bl,'asset_token'));
     if(!preg_match('/^[a-f0-9]{64}$/',$asset)||!self::card_asset_meta($asset))continue;
     $blocks[]=array_merge($geometry,['type'=>'image','asset_token'=>$asset,'url'=>self::card_asset_url($asset),'w'=>max(10,min(90,(float)$scalar($bl,'w',42))),'h'=>max(10,min(90,(float)$scalar($bl,'h',32))),'rotation'=>max(-180,min(180,(float)$scalar($bl,'rotation',0)))]);continue;
    }
    if($type!=='text')continue;$content=mb_substr(sanitize_textarea_field((string)$scalar($bl,'text')),0,1000);if(trim($content)==='')continue;
    $font=sanitize_key((string)$scalar($bl,'font','sans'));
    if(!in_array($font,['sans','serif','handwriting','rounded','elegant','typewriter','playful','bold-display','soft-script','modern','paw-print','cat-scratch','whiskers','bouncy','storybook','party','marker','bubble'],true))$font='sans';
    $align=sanitize_key((string)$scalar($bl,'align','left'));if(!in_array($align,['left','center','right'],true))$align='left';
    $blocks[]=array_merge($geometry,['type'=>'text','text'=>$content,'from_name'=>mb_substr(sanitize_text_field((string)$scalar($bl,'from_name')),0,80),'w'=>max(15,min(95,(float)$scalar($bl,'w',55))),'h'=>max(8,min(90,(float)$scalar($bl,'h',20))),'font_size'=>max(12,min(72,(int)$scalar($bl,'font_size',20))),'rotation'=>max(-15,min(15,(float)$scalar($bl,'rotation',0))),'font'=>$font,'colour'=>sanitize_hex_color((string)$scalar($bl,'colour','#48105f'))?:'#48105f','bold'=>!empty($bl['bold']),'italic'=>!empty($bl['italic']),'underline'=>!empty($bl['underline']),'align'=>$align]);
   }
   if($blocks)$card_pages[]=['blocks'=>$blocks];
  }
  if(!$card_pages)foreach($message_pages as $mp)$card_pages[]=['blocks'=>[['type'=>'text','text'=>$mp,'from_name'=>mb_substr($sender,0,80),'x'=>50,'y'=>35,'w'=>55,'h'=>20,'font_size'=>20,'rotation'=>0,'font'=>'sans','colour'=>'#48105f','bold'=>false,'italic'=>false,'underline'=>false,'align'=>'left']]];
  $date=$text('delivery_date');$delivery_time=$text('delivery_time','09:00');$buyer=sanitize_email($text('buyer_email'));
  $card_mode=sanitize_key($text('card_mode','standard'));if(!in_array($card_mode,['standard','group'],true))$card_mode='standard';
  $card_reveal=sanitize_key($text('card_reveal','gentle'));if(!in_array($card_reveal,['gentle','confetti','hearts','snow','paws','balloons','fireworks','celebration','sparkles','cat-party','none'],true))$card_reveal='gentle';
  $stamp=self::delivery_timestamp(['delivery_date'=>$date,'delivery_time'=>$delivery_time]);
  if(!$recipient||!is_email($email)||!$sender||!$message||!is_email($buyer)||!$stamp||$stamp<time())return new WP_Error('invalid_card','Please complete the recipient, sender, buyer email, message and choose a valid future delivery date and time.');
  return ['recipient_name'=>mb_substr($recipient,0,100),'recipient_email'=>$email,'sender_name'=>mb_substr($sender,0,100),'buyer_email'=>$buyer,'share_buyer_email'=>$text('share_buyer_email')==='yes'?'yes':'no','card_mode'=>$card_mode,'card_reveal'=>$card_reveal,'to_prefix'=>mb_substr($to_prefix,0,40),'from_prefix'=>mb_substr($from_prefix,0,40),'message'=>mb_substr($message,0,1000),'message_pages'=>$message_pages,'card_pages'=>$card_pages,'delivery_date'=>$date,'delivery_time'=>$delivery_time,'delivery_timestamp'=>$stamp];
 }

 public static function ajax_upload_card_image(){check_ajax_referer('ssshop_cart','nonce');if(empty($_FILES['image'])||!is_array($_FILES['image']))wp_send_json_error(['message'=>'Please choose an image.'],400);$f=$_FILES['image'];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||empty($f['tmp_name'])||!is_uploaded_file($f['tmp_name']))wp_send_json_error(['message'=>'The image could not be uploaded.'],400);if((int)($f['size']??0)>5*1024*1024)wp_send_json_error(['message'=>'Images must be 5 MB or smaller.'],400);require_once ABSPATH.'wp-admin/includes/file.php';$check=wp_check_filetype_and_ext($f['tmp_name'],$f['name'],['jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','gif'=>'image/gif']);$mime=$check['type']??'';if(!in_array($mime,['image/jpeg','image/png','image/webp','image/gif'],true))wp_send_json_error(['message'=>'Please upload a JPG, PNG, WebP or GIF image.'],400);$capacity=self::reserve_card_upload((int)($f['size']??0));if(is_wp_error($capacity))wp_send_json_error(['message'=>$capacity->get_error_message()],429);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime];try{$token=bin2hex(random_bytes(32));$name=bin2hex(random_bytes(24)).'.'.$ext;}catch(Exception $e){wp_send_json_error(['message'=>'The image could not be secured.'],500);}$dir=self::card_asset_dir();if(!is_dir($dir)||!is_writable($dir))wp_send_json_error(['message'=>'Private card storage is unavailable.'],500);$dest=trailingslashit($dir).$name;if(!@move_uploaded_file($f['tmp_name'],$dest)){wp_send_json_error(['message'=>'The image could not be stored.'],500);}@chmod($dest,0640);$meta=['file'=>$dest,'mime'=>$mime,'created'=>time()];set_transient(self::card_asset_key($token),$meta,30*DAY_IN_SECONDS);wp_send_json_success(['asset_token'=>$token,'url'=>self::card_asset_url($token)]);}
 public static function ajax_add_cart(){check_ajax_referer('ssshop_cart','nonce');$id=absint($_POST['product_id']??0);if(!self::purchasable($id))wp_send_json_error(['message'=>'This product is not available.'],400);$pers=self::clean_personalisation($id);if(is_wp_error($pers))wp_send_json_error(['message'=>$pers->get_error_message()],400);$c=self::cart();if(count($c)>=30)wp_send_json_error(['message'=>'Your basket can contain up to 30 cards. Please complete checkout before adding more.'],400);$c[]=['line_id'=>str_replace('-','',wp_generate_uuid4()),'product_id'=>$id,'quantity'=>1,'personalisation'=>$pers];self::save_cart($c);wp_send_json_success(self::cart_summary($c));}
