 private static function stripe_request($path,$params){$key=self::stripe_secret();if(!$key)return new WP_Error('stripe_not_configured','Stripe is not configured.');return wp_remote_post('https://api.stripe.com/v1/'.$path,['timeout'=>30,'headers'=>['Authorization'=>'Basic '.base64_encode($key.':')],'body'=>$params]);}
 public static function ajax_checkout(){check_ajax_referer('ssshop_cart','nonce');$items=self::cart_items();if(!$items)wp_send_json_error(['message'=>'Your basket is empty.'],400);if(!self::stripe_secret())wp_send_json_error(['message'=>'Checkout is not configured yet. Please contact the rescue.'],503);foreach($items as &$item){$personalisation=self::clean_personalisation($item['product_id'],$item['personalisation']??[]);if(is_wp_error($personalisation))wp_send_json_error(['message'=>$personalisation->get_error_message()],400);$item['personalisation']=$personalisation;$item['card_reveal']=$personalisation['card_reveal']??'none';}unset($item);$total=array_sum(array_map(fn($i)=>$i['unit_amount']*$i['quantity'],$items));$order=wp_insert_post(['post_type'=>self::ORDER_TYPE,'post_status'=>'publish','post_title'=>'Order '.gmdate('Y-m-d H:i:s')],true);if(is_wp_error($order))wp_send_json_error(['message'=>'Could not create order.'],500);update_post_meta($order,'_ssshop_order_status','pending_payment');update_post_meta($order,'_ssshop_order_total',$total);update_post_meta($order,'_ssshop_order_items',$items);update_post_meta($order,'_ssshop_order_mode',get_option('ssshop_stripe_mode','test'));$buyer='';foreach($items as $bi){$be=sanitize_email($bi['personalisation']['buyer_email']??'');if($be){$buyer=$be;break;}}if($buyer)update_post_meta($order,'_ssshop_buyer_email',$buyer);
  $basket=self::shortcode_page_url('rescue_shop_basket','/basket/');$params=['mode'=>'payment','payment_method_types[0]'=>'card','success_url'=>add_query_arg(['ssshop_payment'=>'success','order'=>$order],$basket).'&session_id={CHECKOUT_SESSION_ID}','cancel_url'=>add_query_arg(['ssshop_payment'=>'cancelled','order'=>$order],$basket),'client_reference_id'=>(string)$order,'metadata[ssshop_order_id]'=>(string)$order,'payment_intent_data[metadata][ssshop_order_id]'=>(string)$order];if($buyer)$params['customer_email']=$buyer;$n=0;foreach($items as $i){$params['line_items['.$n.'][price_data][currency]']='gbp';$params['line_items['.$n.'][price_data][product_data][name]']=$i['name'];$params['line_items['.$n.'][price_data][unit_amount]']=$i['unit_amount'];$params['line_items['.$n.'][quantity]']=$i['quantity'];$n++;}
  $r=self::stripe_request('checkout/sessions',$params);if(is_wp_error($r)){update_post_meta($order,'_ssshop_order_status','checkout_error');wp_send_json_error(['message'=>$r->get_error_message()],500);}$body=json_decode(wp_remote_retrieve_body($r),true);if(wp_remote_retrieve_response_code($r)>=300||empty($body['url'])||empty($body['id'])){update_post_meta($order,'_ssshop_order_status','checkout_error');wp_send_json_error(['message'=>'Stripe could not start checkout.'],500);}update_post_meta($order,'_ssshop_stripe_session',sanitize_text_field($body['id']));wp_send_json_success(['url'=>esc_url_raw($body['url'])]);}
 private static function verify_stripe_signature($payload,$header,$secret){$parts=[];foreach(explode(',',$header) as $p){$kv=explode('=',$p,2);if(count($kv)===2)$parts[$kv[0]][]=$kv[1];}$t=$parts['t'][0]??'';$sigs=$parts['v1']??[];if(!$t||abs(time()-(int)$t)>300)return false;$expected=hash_hmac('sha256',$t.'.'.$payload,$secret);foreach($sigs as $s)if(hash_equals($expected,$s))return true;return false;}
 public static function stripe_webhook(WP_REST_Request $req) {
  $payload=$req->get_body();$event=json_decode($payload,true,32);
  if(!is_array($event)||!isset($event['livemode'])||!is_bool($event['livemode']))return new WP_REST_Response(['error'=>'Invalid event'],400);
  $mode=$event['livemode']?'live':'test';$secret=trim(get_option('ssshop_stripe_'.$mode.'_webhook',''));
  if(!$secret||!self::verify_stripe_signature($payload,$req->get_header('stripe-signature'),$secret))return new WP_REST_Response(['error'=>'Invalid signature'],400);
  if(($event['type']??'')!=='checkout.session.completed')return new WP_REST_Response(['received'=>true],200);
  $session=$event['data']['object']??null;
  if(!is_array($session))return new WP_REST_Response(['error'=>'Invalid session'],400);
  $order=absint($session['metadata']['ssshop_order_id']??$session['client_reference_id']??0);
  if(!$order||get_post_type($order)!==self::ORDER_TYPE)return new WP_REST_Response(['error'=>'Unknown order'],400);
  $saved_session=(string)get_post_meta($order,'_ssshop_stripe_session',true);
  $session_id=is_string($session['id']??null)?$session['id']:'';
  $expected=(int)get_post_meta($order,'_ssshop_order_total',true);
  if(!$saved_session||!hash_equals($saved_session,$session_id)||get_post_meta($order,'_ssshop_order_mode',true)!==$mode||$expected<1||!is_int($session['amount_total']??null)||$session['amount_total']!==$expected||($session['currency']??'')!=='gbp'||($session['payment_status']??'')!=='paid')return new WP_REST_Response(['error'=>'Payment does not match order'],400);
  $lock='ssshop_webhook_lock_'.$order;
  if(!add_option($lock,time(),'','no')){
   $created=(int)get_option($lock);if($created&&$created<time()-300){delete_option($lock);return new WP_REST_Response(['error'=>'Retry event'],409);}
   return new WP_REST_Response(['error'=>'Order is being processed'],409);
  }
  try {
   // Stripe retries delivery. Never replace existing cards or resend a paid order.
   if(get_post_meta($order,'_ssshop_order_status',true)==='paid')return new WP_REST_Response(['received'=>true],200);
   $items=get_post_meta($order,'_ssshop_order_items',true);$tokens=[];
   if(!is_array($items))return new WP_REST_Response(['error'=>'Order items missing'],400);
   foreach($items as $item){
    if(!is_array($item)||($item['digital_kind']??'')!=='ecard'||!is_array($item['personalisation']??null)||!$item['personalisation'])continue;
    $pers=$item['personalisation'];$owner='sender-'.bin2hex(random_bytes(12));$pages=[];
    if(!empty($pers['card_pages'])&&is_array($pers['card_pages'])){
     foreach($pers['card_pages'] as $page){$blocks=[];foreach(is_array($page['blocks']??null)?$page['blocks']:[] as $block){if(!is_array($block))continue;$block['owner_id']=$owner;$blocks[]=$block;}if($blocks)$pages[]=['type'=>'canvas','blocks'=>$blocks];}
    } else {
     foreach(is_array($pers['message_pages']??null)?$pers['message_pages']:[$pers['message']??''] as $message){if(is_string($message)&&$message!=='')$pages[]=['type'=>'message','message'=>$message,'owner_id'=>$owner];}
    }
    self::persist_card_assets($pages);
    $tokens[]=['token'=>bin2hex(random_bytes(24)),'manage_token'=>bin2hex(random_bytes(32)),'sender_owner_id'=>$owner,'product_id'=>absint($item['product_id']??0),'card_reveal'=>$item['card_reveal']??'gentle','personalisation'=>$pers,'card_mode'=>$pers['card_mode']??'standard','group_token'=>(($pers['card_mode']??'standard')==='group'?bin2hex(random_bytes(24)):''),'card_schema'=>3,'pages'=>$pages,'delivery_status'=>'scheduled','attempts'=>0];
   }
   update_post_meta($order,'_ssshop_card_tokens',$tokens);self::index_card_tokens($order,$tokens);
   $stripe_email=sanitize_email(is_scalar($session['customer_details']['email']??null)?(string)$session['customer_details']['email']:'');
   update_post_meta($order,'_ssshop_customer_email',$stripe_email);
   if(!get_post_meta($order,'_ssshop_buyer_email',true)&&$stripe_email)update_post_meta($order,'_ssshop_buyer_email',$stripe_email);
   update_post_meta($order,'_ssshop_paid_at',current_time('mysql',true));
   update_post_meta($order,'_ssshop_stripe_payment_intent',sanitize_text_field(is_string($session['payment_intent']??null)?$session['payment_intent']:''));
   update_post_meta($order,'_ssshop_order_status','paid');
   self::send_order_confirmation($order);
   foreach($tokens as $index=>$entry){$due=self::delivery_timestamp($entry['personalisation']);if($due&&$due<=time())self::deliver_card_entry($order,$index);}
   return new WP_REST_Response(['received'=>true],200);
  } finally { delete_option($lock); }
 }

