 private static function basket_url(){return self::shortcode_page_url('rescue_shop_basket','/basket/');}
 public static function catalogue($atts=[]){self::assets();$atts=shortcode_atts(['category'=>'','featured'=>'','limit'=>'24'],$atts,'straysafe_shop');$meta=[['key'=>'_ssshop_visibility','value'=>'catalogue']];if($atts['featured']==='yes')$meta[]=['key'=>'_ssshop_featured','value'=>'yes'];$args=['post_type'=>self::POST_TYPE,'post_status'=>'publish','posts_per_page'=>max(1,min(100,absint($atts['limit']))),'meta_query'=>$meta];if($atts['category']!=='')$args['tax_query']=[['taxonomy'=>self::TAXONOMY,'field'=>'slug','terms'=>sanitize_title($atts['category'])]];$q=new WP_Query($args);$s=self::cart_summary();$cats=get_terms(['taxonomy'=>self::TAXONOMY,'hide_empty'=>true]);$sustain=trim((string)get_option('ssshop_sustainability',''));if($sustain==='')$sustain='Choose digital where available for a paper-free way to send something special while supporting cats in need.';ob_start();echo '<section data-rps-ui class="ssshop"><header class="ssshop-header"><div class="ssshop-intro-copy"><h2>'.esc_html(get_option('ssshop_shop_title','Rescue Shop')).'</h2>';$intro=trim((string)get_option('ssshop_intro',''));if($intro!=='')echo '<p>'.esc_html($intro).'</p>';echo '</div><a class="ssshop-cart-summary" href="'.esc_url(self::basket_url()).'">🛒 <span data-ssshop-cart-count>'.esc_html($s['count']).'</span> item(s) · <span data-ssshop-cart-total>'.esc_html($s['formatted']).'</span></a></header><div class="ssshop-sustainability"><span aria-hidden="true">🌱</span><span>'.esc_html($sustain).'</span></div><div class="ssshop-filters" aria-label="Shop filters"><div class="ssshop-format-filter" role="group" aria-label="Product format"><button type="button" class="is-active" data-shop-format="all">All</button><button type="button" data-shop-format="digital">Digital</button><button type="button" data-shop-format="physical">Physical</button></div>';if(!is_wp_error($cats)&&$cats){echo '<label class="ssshop-category-filter"><span>Category</span><select data-shop-category><option value="all">All categories</option>';foreach($cats as $cat)echo '<option value="'.esc_attr($cat->slug).'">'.esc_html($cat->name).'</option>';echo '</select></label>';}echo '</div><div class="ssshop-grid" data-shop-grid>';while($q->have_posts()){$q->the_post();self::render_product(get_the_ID());}if(!$q->post_count)echo '<p>No products are currently available.</p>';echo '</div><p class="ssshop-filter-empty" data-shop-filter-empty hidden>No products match those filters.</p></section>';wp_reset_postdata();return ob_get_clean();}
 public static function product_shortcode($atts=[]){self::assets();$id=absint(shortcode_atts(['id'=>0],$atts)['id']);if(!self::purchasable($id))return'';ob_start();echo '<div data-rps-ui class="ssshop ssshop-grid">';self::render_product($id);echo '</div>';return ob_get_clean();}
 private static function shortcode_page_url($shortcode,$fallback='/') {
  $aliases=['rescue_shop'=>'straysafe_shop','rescue_shop_basket'=>'straysafe_shop_basket','rescue_shop_product'=>'straysafe_shop_product'];
  $tags=[$shortcode]; if(isset($aliases[$shortcode]))$tags[]=$aliases[$shortcode];
  foreach($tags as $tag){$pages=get_posts(['post_type'=>'page','post_status'=>'publish','numberposts'=>100,'s'=>$tag]);foreach($pages as $page)if(has_shortcode($page->post_content,$tag))return get_permalink($page);}
  return home_url($fallback);
 }
 private static function display_date($date){$dt=\DateTimeImmutable::createFromFormat('!Y-m-d',(string)$date);return $dt?$dt->format('d/m/Y'):(string)$date;} private static function display_delivery($date,$time=''){if(!$date)return'';$tz=wp_timezone();$dt=\DateTimeImmutable::createFromFormat('!Y-m-d H:i',(string)$date.' '.($time?:'09:00'),$tz);return $dt?$dt->format('d/m/Y \a\t H:i'):self::display_date($date).($time?' at '.$time:'');} private static function delivery_timestamp($pers){$date=(string)($pers['delivery_date']??'');$time=(string)($pers['delivery_time']??'09:00');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$time))return 0;$dt=\DateTimeImmutable::createFromFormat('!Y-m-d H:i',$date.' '.$time,wp_timezone());return $dt&&$dt->format('Y-m-d H:i')===$date.' '.$time?$dt->getTimestamp():0;}
 public static function basket_shortcode(){self::assets();$c=self::cart();$s=self::cart_summary($c);self::assets();$shop=self::shortcode_page_url('rescue_shop','/shop/');$return_state=sanitize_key(wp_unslash($_GET['ssshop_payment']??''));$return_order=absint($_GET['order']??0);$return_session=sanitize_text_field(wp_unslash($_GET['session_id']??''));$verified_paid=$return_state==='success'&&$return_order&&$return_session&&get_post_meta($return_order,'_ssshop_stripe_session',true)===$return_session&&get_post_meta($return_order,'_ssshop_order_status',true)==='paid';if($verified_paid){self::save_cart([]);$c=[];$s=self::cart_summary($c);}ob_start();echo '<section data-rps-ui class="ssshop ssshop-basket"><h2>Your basket</h2>';if(($_GET['ssshop_payment']??'')==='cancelled')echo '<div class="ssshop-alert ssshop-alert-info"><strong>Checkout cancelled</strong><br>Your basket is still here if you would like to continue.</div>';elseif($return_state==='success'){if($verified_paid){echo '<div class="ssshop-payment-complete"><div class="ssshop-payment-icon">✓</div><h3>Thank you. Your payment is confirmed.</h3><p>Your order <strong>#'.esc_html($return_order).'</strong> has been paid successfully.</p><p>Your e-card is scheduled for its chosen delivery date. We will email it directly to the recipient.</p><a class="ssshop-continue" href="'.esc_url($shop).'">Continue shopping</a></div></section>';return ob_get_clean();}else echo '<div class="ssshop-alert ssshop-alert-info" data-ssshop-verifying data-order="'.esc_attr($return_order).'" data-session="'.esc_attr($return_session).'"><strong>Payment submitted</strong><br>We are confirming your payment securely with Stripe. Please keep this page open for a moment.</div>';}echo '<div data-ssshop-basket>';if(!$s['count'])echo '<p>Your basket is empty.</p>';foreach(self::cart_items($c) as $i){$ecard=$i['digital_kind']==='ecard'&&!empty($i['personalisation']);echo '<div class="ssshop-basket-row" data-ssshop-basket-row="'.esc_attr($i['line_id']).'"><div class="ssshop-basket-main"><strong>'.esc_html($i['name']).'</strong>';if($ecard){$pers=$i['personalisation'];echo '<span class="ssshop-basket-kind">Interactive e-card</span><small>For '.esc_html($pers['recipient_name']).' · Delivery '.esc_html(self::display_delivery($pers['delivery_date'],$pers['delivery_time']??'09:00')).'</small><details class="ssshop-basket-edit"><summary>Edit personalisation</summary><div class="ssshop-basket-edit-fields"><label>Recipient name<input name="recipient_name" value="'.esc_attr($pers['recipient_name']).'" maxlength="100" required></label><label>Recipient email<input name="recipient_email" type="email" value="'.esc_attr($pers['recipient_email']).'" required></label><label>Your name<input name="sender_name" value="'.esc_attr($pers['sender_name']).'" maxlength="100" required></label><div class="ssshop-basket-message-pages" data-basket-message-pages>';foreach(($pers['message_pages']??[$pers['message']]) as $mpi=>$mp)echo '<label>Message page '.($mpi+1).'<textarea name="message_page_'.absint($mpi).'" data-basket-message-page maxlength="1000" rows="4" required>'.esc_textarea($mp).'</textarea></label>';echo '</div><label>Delivery date<input name="delivery_date" type="date" min="'.esc_attr(wp_date('Y-m-d')).'" value="'.esc_attr($pers['delivery_date']).'" required></label><label>Delivery time<input name="delivery_time" type="time" value="'.esc_attr($pers['delivery_time']??'09:00').'" required></label><button type="button" class="ssshop-save-edit" data-ssshop-save-line="'.esc_attr($i['line_id']).'">Save changes</button></div></details>';}else echo '<small>£'.esc_html(number_format($i['unit_amount']/100,2)).' each</small>';echo '</div><div class="ssshop-basket-side"><strong>£'.esc_html(number_format(($i['unit_amount']*$i['quantity'])/100,2)).'</strong>';if($ecard)echo '<button type="button" class="ssshop-link-button" data-ssshop-remove-line="'.esc_attr($i['line_id']).'">Remove</button>';else echo '<label>Quantity <input class="ssshop-qty" type="number" min="0" max="20" value="'.esc_attr($i['quantity']).'" data-ssshop-line="'.esc_attr($i['line_id']).'"></label>';echo '</div></div>';}echo '</div><div class="ssshop-basket-footer"><a class="ssshop-continue" href="'.esc_url($shop).'">Continue shopping</a><div><div class="ssshop-basket-total"><strong>Total: <span data-ssshop-cart-total>'.esc_html($s['formatted']).'</span></strong></div>';$configured=(bool)self::stripe_secret();echo '<button class="ssshop-checkout" type="button" data-ssshop-checkout '.disabled(!$configured||!$s['count'],true,false).'>'.($configured?'Secure checkout · '.esc_html($s['formatted']):'Checkout not configured').'</button></div></div><p class="ssshop-notice" data-ssshop-checkout-message>'.($configured?'Payment is completed securely on Stripe. The rescue does not receive your card details.':'Stripe test credentials must be configured by an administrator before checkout can be used.').'</p></section>';return ob_get_clean();}
 private static function render_product($id){$format=get_post_meta($id,'_ssshop_type',true)?:'digital';if(!in_array($format,['digital','physical'],true))$format='digital';$p=(int)get_post_meta($id,'_ssshop_price_pence',true);$kind=get_post_meta($id,'_ssshop_digital_kind',true)?:'other';$labels=['ecard'=>'Interactive e-card','download'=>'Digital download','other'=>'Digital product'];$is_card=$format==='digital'&&$kind==='ecard';$terms=wp_get_post_terms($id,self::TAXONOMY,['fields'=>'slugs']);$catdata=is_wp_error($terms)?'':implode(' ',array_map('sanitize_title',$terms));echo '<article class="ssshop-card" data-card-product="'.esc_attr($id).'" data-shop-format="'.esc_attr($format).'" data-shop-categories="'.esc_attr($catdata).'">';if(has_post_thumbnail($id)){if($is_card)echo '<button type="button" class="ssshop-product-open ssshop-image" data-ssshop-personalise aria-label="Personalise '.esc_attr(get_the_title($id)).'">'.get_the_post_thumbnail($id,'medium_large',['loading'=>'lazy']).'</button>';else echo '<div class="ssshop-image">'.get_the_post_thumbnail($id,'medium_large',['loading'=>'lazy']).'</div>';}echo '<div class="ssshop-content"><span class="ssshop-type">'.esc_html($format==='physical'?'Physical product':($labels[$kind]??'Digital product')).'</span>';if($is_card)echo '<h3><button type="button" class="ssshop-title-open" data-ssshop-personalise>'.esc_html(get_the_title($id)).'</button></h3>';else echo '<h3>'.esc_html(get_the_title($id)).'</h3>';echo '<p>'.esc_html(wp_trim_words(get_the_excerpt($id)?:wp_strip_all_tags(get_post_field('post_content',$id)),22)).'</p><div class="ssshop-card-footer"><strong class="ssshop-price">£'.esc_html(number_format($p/100,2)).'</strong>';if($is_card){echo '<button type="button" class="ssshop-personalise" data-ssshop-personalise>Personalise &amp; Send</button></div><div data-rps-ui class="ssshop-modal" data-ssshop-modal hidden role="dialog" aria-modal="true" aria-labelledby="ssshop-modal-title-'.esc_attr($id).'"><div class="ssshop-