 private static function manage_url($token){return add_query_arg('ssshop_manage',rawurlencode($token),home_url('/'));}
 private static function audit_card(&$entry,$action,$detail='',$actor='sender'){$entry['audit']=is_array($entry['audit']??null)?$entry['audit']:[];$entry['audit'][]=['at'=>current_time('mysql',true),'action'=>sanitize_key($action),'detail'=>sanitize_text_field($detail),'actor'=>sanitize_text_field($actor)];if(count($entry['audit'])>50)$entry['audit']=array_slice($entry['audit'],-50);}
 private static function card_url($token){return add_query_arg('ssshop_card',rawurlencode($token),home_url('/'));}
 private static function send_order_confirmation($order,$force=false){if(!$force&&get_post_meta($order,'_ssshop_confirmation_sent',true))return true;$to=sanitize_email(get_post_meta($order,'_ssshop_buyer_email',true)?:get_post_meta($order,'_ssshop_customer_email',true));if(!$to)return false;$items=get_post_meta($order,'_ssshop_order_items',true);$total=(int)get_post_meta($order,'_ssshop_order_total',true);$products=[];if(is_array($items))foreach($items as $i){$line=($i['name']??'Product').' × '.absint($i['quantity']??1);if(($i['digital_kind']??'')==='ecard'&&!empty($i['personalisation'])){$p=$i['personalisation'];$line.=' — For '.($p['recipient_name']??'').' · Delivery '.self::display_delivery($p['delivery_date']??'',$p['delivery_time']??'09:00');}$products[]=$line;}$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(is_array($tokens))foreach($tokens as $te){if(!empty($te['manage_token']))$products[]='Manage your card: '.self::manage_url($te['manage_token']);if(!empty($te['group_token']))$products[]='Group card contribution link: '.self::group_url($te['group_token']);}$repl=['{order_number}'=>(string)absint($order),'{products}'=>implode("\n",$products),'{total}'=>'£'.number_format($total/100,2),'{customer_email}'=>$to];$subject=strtr(get_option('ssshop_order_subject','Rescue Shop order #{order_number} confirmed'),$repl);$heading=strtr(get_option('ssshop_order_heading','Thank you for your order'),$repl);$bodytext=strtr(get_option('ssshop_order_body',"Your Rescue Shop order #{order_number} is confirmed and paid.\n\n{products}\n\nTotal: {total}\n\nStripe may send a separate payment receipt."),$repl);$body='<div style="font-family:Arial,sans-serif;max-width:620px;margin:30px auto;padding:30px;border:1px solid #eee;border-radius:16px"><h1 style="color:#48105f">'.esc_html($heading).'</h1><div style="line-height:1.6;white-space:pre-line">'.nl2br(esc_html($bodytext)).'</div></div>';$ok=self::send_shop_email($to,$subject,$body,self::default_no_reply());if($ok)update_post_meta($order,'_ssshop_confirmation_sent',current_time('mysql',true));return $ok;}
 private static function buyer_owner($entry){if(!empty($entry['sender_owner_id']))return sanitize_text_field($entry['sender_owner_id']);return 'buyer-'.substr(hash('sha256',(string)($entry['manage_token']??'')),0,32);}
 private static function normalise_card_owners(&$entry){$owner=self::buyer_owner($entry);if(!empty($entry['pages'])&&is_array($entry['pages']))foreach($entry['pages'] as &$p)if(!empty($p['blocks'])&&is_array($p['blocks']))foreach($p['blocks'] as &$b)if(is_array($b)&&empty($b['owner_id']))$b['owner_id']=$owner;unset($b,$p);}
 private static function media_context($token,$kind){if($kind==='manage')return self::find_manage_card($token);if($kind==='group')return self::find_group_card($token);return false;}

 private static function card_token_index($token){return 'ssshop_card_index_'.hash('sha256',$token);}
 private static function index_card_tokens($order,$tokens){foreach($tokens as $index=>$entry)foreach(['token','manage_token','group_token'] as $field)if(!empty($entry[$field])&&is_string($entry[$field]))add_option(self::card_token_index($entry[$field]),['order'=>absint($order),'index'=>absint($index)],'','no');}
 private static function find_card_token($token,$field){
  if(!is_string($token)||!preg_match('/^[a-f0-9]{48,64}$/',$token))return false;
  $location=get_option(self::card_token_index($token),false);
  if(is_array($location)){$order=absint($location['order']??0);$index=absint($location['index']??0);$tokens=get_post_meta($order,'_ssshop_card_tokens',true);$entry=$tokens[$index]??null;if(get_post_type($order)===self::ORDER_TYPE&&get_post_meta($order,'_ssshop_order_status',true)==='paid'&&is_array($entry)&&is_string($entry[$field]??null)&&hash_equals($entry[$field],$token))return[$order,$index,$entry];}
  $page=1;
  do{$orders=get_posts(['post_type'=>self::ORDER_TYPE,'post_status'=>'publish','posts_per_page'=>100,'paged'=>$page++,'orderby'=>'ID','order'=>'DESC','meta_query'=>['relation'=>'AND',['key'=>'_ssshop_order_status','value'=>'paid'],['key'=>'_ssshop_card_tokens','value'=>$token,'compare'=>'LIKE']],'fields'=>'ids']);foreach($orders as $order){$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(!is_array($tokens))continue;foreach($tokens as $index=>$entry)if(is_array($entry)&&is_string($entry[$field]??null)&&hash_equals($entry[$field],$token)){self::index_card_tokens($order,$tokens);self::persist_card_assets($entry['pages']??[]);return[$order,$index,$entry];}}}while(count($orders)===100);
  return false;
 }
 private static function find_manage_card($token){return self::find_card_token($token,'manage_token');}

 public static function ajax_media_search(){check_ajax_referer('ssshop_media','nonce');$context=sanitize_key(wp_unslash($_POST['context']??''));$token=sanitize_text_field(wp_unslash($_POST['token']??''));if(!self::media_context($token,$context))wp_send_json_error(['message'=>'Card access could not be verified.'],403);$type=sanitize_key(wp_unslash($_POST['media_type']??'gif'));$q=trim(sanitize_text_field(wp_unslash($_POST['query']??'')));if($type==='image')wp_send_json_error(['message'=>'Web image search is not configured yet. You can still upload your own image.'],501);$key=trim(get_option('ssshop_giphy_key',''));if(!$key)wp_send_json_error(['message'=>'GIF search is not configured yet. Add a GIPHY API key in Rescue Shop Settings.'],501);if($q==='')wp_send_json_error(['message'=>'Enter something to search for.'],400);$url=add_query_arg(['api_key'=>$key,'q'=>$q,'limit'=>18,'rating'=>'pg','lang'=>'en','bundle'=>'messaging_non_clips'],'https://api.giphy.com/v1/gifs/search');$r=wp_remote_get($url,['timeout'=>12]);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)!==200)wp_send_json_error(['message'=>'GIF search is temporarily unavailable.'],502);$data=json_decode(wp_remote_retrieve_body($r),true);$items=[];foreach(array_slice($data['data']??[],0,18) as $g){$im=$g['images']['fixed_width']??[];$orig=$g['images']['original']??[];$remote=esc_url_raw($orig['url']??'');$preview=esc_url_raw($im['url']??$remote);if($remote&&$preview)$items[]=['title'=>sanitize_text_field($g['title']??'GIF'),'preview'=>$preview,'remote'=>$remote];}wp_send_json_success(['items'=>$items,'attribution'=>'Powered by GIPHY']);}
 public static function ajax_media_import(){check_ajax_referer('ssshop_media','nonce');$context=sanitize_key(wp_unslash($_POST['context']??''));$token=sanitize_text_field(wp_unslash($_POST['token']??''));if(!self::media_context($token,$context))wp_send_json_error(['message'=>'Card access could not be verified.'],403);$remote=esc_url_raw(wp_unslash($_POST['remote']??''));$host=strtolower((string)wp_parse_url($remote,PHP_URL_HOST));if(!$remote||!preg_match('/(^|\\.)giphy\\.com$|(^|\\.)giphyusercontent\\.com$|(^|\\.)media[0-9]*\\.giphy\\.com$/',$host))wp_send_json_error(['message'=>'That media source is not allowed.'],400);$r=wp_safe_remote_get($remote,['timeout'=>20,'redirection'=>3,'limit_response_size'=>8388608]);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)!==200)wp_send_json_error(['message'=>'The selected GIF could not be imported.'],502);$body=wp_remote_retrieve_body($r);if(strlen($body)>8388608)wp_send_json_error(['message'=>'That GIF is too large. Choose one under 8 MB.'],400);$ctype=strtolower(trim(explode(';',(string)wp_remote_retrieve_header($r,'content-type'))[0]??''));if($ctype!=='image/gif')wp_send_json_error(['message'=>'The selected result was not a GIF.'],400);$capacity=self::reserve_card_upload(strlen($body));if(is_wp_error($capacity))wp_send_json_error(['message'=>$capacity->get_error_message()],429);$asset=bin2hex(random_bytes(32));$dest=trailingslashit(self::card_asset_dir()).bin2hex(random_bytes(24)).'.gif';if(file_put_contents($dest,$body)===false)wp_send_json_error(['message'=>'The GIF could not be stored.'],500);@chmod($dest,0640);set_transient(self::card_asset_key($asset),['file'=>$dest,'mime'=>'image/gif','created'=>time()],30*DAY_IN_SECONDS);wp_send_json_success(['asset_token'=>$asset,'url'=>self::card_asset_url($asset)]);}

 private static function edit_card_entry($order,$index,$callback){
  $lock='ssshop_delivery_lock_'.absint($order);
  if(!add_option($lock,time(),'','no')){if((int)get_option($lock)<time()-300)delete_option($lock);return new WP_Error('card_busy','This card is being updated. Please try saving again.');}
  try{$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(!is_array($tokens)||!is_array($tokens[$index]??null))return new WP_Error('missing_card','Card not found.');$entry=$tokens[$index];if(self::card_locked($entry))return new WP_Error('card_locked','This card has already been delivered and is locked.');self::normalise_card_owners($entry);$result=$callback($entry);if(is_wp_error($result))return $result;self::persist_card_assets($entry['pages']??[]);$tokens[$index]=$entry;update_post_meta($order,'_ssshop_card_tokens',$tokens);return true;}finally{delete_option($lock);}
 }
 private static function merge_card_pages(&$entry,$raw,$owner,$name,$prefix='From'){
  $existing=array_values(is_array($entry['pages']??null)?$entry['pages']:[]);$clean=[];
  foreach(array_slice($raw,0,6) as $page){if(!is_array($page))continue;$index=absint($page['page_index']??count($existing));if($index>5)return new WP_Error('page_limit','Cards can contain up to six inside pages.');$blocks=self::group_blocks($page['blocks']??[],$owner,$name,$prefix);if($blocks)$clean[$index]=$blocks;}
  foreach($existing as $index=>&$page){$page['type']='canvas';$page['blocks']=array_values(array_filter(is_array($page['blocks']??null)?$page['blocks']:[],static function($block)use($owner){return is_array($block)&&($block['owner_id']??'')!==$owner;}));if(isset($clean[$index])){$page['blocks']=array_merge($page['blocks'],$clean[$index]);unset($clean[$index]);}if(count($page['blocks'])>100)return new WP_Error('block_limit','This page is full. Please use another page.');}unset($page);
  foreach($clean as $blocks)$existing[]=['type'=>'canvas','blocks'=>$blocks,'contributor_name'=>$name,'contributed_at'=>current_time('mysql',true)];
  if(count($existing)>6)return new WP_Error('page_limit','Cards can contain up to six inside pages.');$entry['pages']=$existing;return true;
 }
 public static function ajax_manage_design(){
  check_ajax_referer('ssshop_manage_design','nonce');$token=sanitize_text_field(wp_unslash($_POST['manage_token']??''));$raw=json_decode(is_string($_POST['pages']??null)?wp_unslash($_POST['pages']):'[]',true,24);$found=self::find_manage_card($token);
  if(!$found||!is_array($raw))wp_send_json_error(['message'=>'Card not found.'],404);[$order,$index]=$found;
  $result=self::edit_card_entry($order,$index,static function(&$entry)use($raw){$owner=self::buyer_owner($entry);$name=sanitize_text_field($entry['personalisation']['sender_name']??'');$result=self::merge_card_pages($entry,$raw,$owner,$name);if(!is_wp_error($result))self::audit_card($entry,'sender_design_updated','Purchaser updated their own card content','sender');return $result;});
  if(is_wp_error($result))wp_send_json_error(['message'=>$result->get_error_message()],409);wp_send_json_success(['message'=>'Your card design has been saved.']);
 }

 public static function sender_card_manage(){if(empty($_GET['ssshop_manage']))return;header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet',true);header('Referrer-Policy: no-referrer',true);$token=sanitize_text_field(wp_unslash($_GET['ssshop_manage']));$found=self::find_manage_card($token);if(!$found){status_header(404);exit('Card management link not found.');}[$order,$index,$entry]=$found;self::normalise_card_owners($entry);$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce']??'')),'ssshop_manage_'.$token))wp_die('This request could not be verified.');$tokens=get_post_meta($order,'_ssshop_card_tokens',true);$entry=$tokens[$index];$pers=$entry['personalisation']??[];$email=sanitize_email(wp_unslash($_POST['recipient_email']??''));$action=sanitize_key(wp_unslash($_POST['manage_action']??'save'));if(!$email||!is_email($email))$notice='Please enter a valid recipient email address.';else{if(empty($entry['sent_at']))$pers['recipient_email']=$email;if(empty($entry['sent_at'])){$date=sanitize_text_field(wp_unslash($_POST['delivery_date']??''));$time=sanitize_text_field(wp_unslash($_POST['delivery_time']??''));$reveal=sanitize_key(wp_unslash($_POST['card_reveal']??($pers['card_reveal']??'gentle')));if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$date)||!preg_match('/^\\d{2}:\\d{2}$/',$time))$notice='Please choose a valid delivery date and time.';else{$pers['delivery_date']=$date;$pers['delivery_time']=$time;$pers['delivery_timestamp']=self::delivery_timestamp(['delivery_date'=>$date,'delivery_time'=>$time]);if(in_array($reveal,['gentle','confetti','hearts','snow','paws','balloons','fireworks','celebration','sparkles','cat-party','none'],true)){$pers['card_reveal']=$reveal;$entry['card_reveal']=$reveal;}$entry['delivery_status']='scheduled';self::audit_card($entry,'sender_rescheduled','Delivery '.$date.' '.$time,'sender');}}if(!$notice){if(!empty($entry['sent_at']))$pers['recipient_email']=$entry['personalisation']['recipient_email']??$pers['recipient_email'];$entry['personalisation']=$pers;$tokens[$index]=$entry;update_post_meta($order,'_ssshop_card_tokens',$tokens);if($action==='resend'&&!empty($entry['sent_at'])){$r=self::deliver_card_entry($order,$index,true);$notice=is_wp_error($r)?'The email was saved, but the card email could not be resent.':'The card email has been resent.';}else$notice=empty($entry['sent_at'])?'Your card details have been updated.':'The recipient email address has been updated.';}}}$entry=get_post_meta($order,'_ssshop_card_tokens',true)[$index];$pers=$entry['personalisation']??[];$sent=!empty($entry['sent_at']);$edit=add_query_arg(['ssshop_group'=>$entry['group_token']??'','ssshop_buyer'=>$entry['manage_token']??''],home_url('/'));status_header(200);nocache_headers();echo '<!doctype html><html lang="'.esc_attr(get_bloginfo('language')).'"><head><meta charset="'.esc_attr(get_bloginfo('charset')).'"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive,nosnippet"><title>Manage your rescue e-card</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f2f8;color:#29242b;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:760px;margin:auto;padding:40px 18px}.panel{background:#fff;padding:32px;border-radius:18px;box-shadow:0 15px 40px #35123f18}h1,h2{color:#48105f}label{display:block;font-weight:650;margin:16px 0}input,select{width:100%;padding:11px;margin-top:6px;border:1px solid #d8cedc;border-radius:8px;font:inherit}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:999px;background:#48105f;color:#fff;padding:12px 19px;font-weight:700;cursor:pointer;text-decoration:none}.secondary{background:#eee5f0;color:#48105f}.notice{padding:12px;background:#eef7ee;border-radius:8px}.meta{padding:12px;background:#f7f2f8;border-radius:9px}.design{margin:22px 0;padding:18px;border:1px solid #e5dce8;border-radius:14px}@media(max-width:520px){.row{grid-template-columns:1fr}}</style></head><body><main class="wrap"><section class="panel"><h1>Manage your e-card</h1><p>For '.esc_html($pers['recipient_name']??'your recipient').'.</p>';if($notice)echo '<p class="notice">'.esc_html($notice).'</p>';echo '<div class="meta">Status: <strong>'.esc_html($sent?'Sent':'Scheduled').'</strong>';if($sent)echo '<br>Sent: '.esc_html($entry['sent_at']).' UTC';echo '</div><div class="design"><h2>Your card content</h2>';if($sent)echo '<p>This card has been delivered and its content is now locked. You can still view the delivered card, but its messages, photos, GIFs and contributions can no longer be changed.</p><a class="btn secondary" href="'.esc_url(self::card_url($entry['token'])).'">View delivered card</a>';else echo '<p>See the complete group card and amend your own messages, stickers, photos and GIFs. Other people’s contributions remain visible but locked.</p><a class="btn" href="'.esc_url($edit).'">View and edit card</a>';echo '</div><form method="post">'.wp_nonce_field('ssshop_manage_'.$token,'_wpnonce',true,false).'<label>Recipient email<input type="email" name="recipient_email" value="'.esc_attr($pers['recipient_email']??'').'" required></label>';if(!$sent){echo '<div class="row"><label>Delivery date<input type="date" name="delivery_date" value="'.esc_attr($pers['delivery_date']??'').'" required></label><label>Delivery time<input type="time" name="delivery_time" value="'.esc_attr($pers['delivery_time']??'09:00').'" required></label></div><label>Card opening animation<select name="card_reveal">';foreach(['gentle'=>'Gentle reveal','confetti'=>'Confetti','hearts'=>'Hearts','snow'=>'Snow','paws'=>'Paw prints','balloons'=>'Balloons','fireworks'=>'Fireworks','celebration'=>'Celebration burst','sparkles'=>'Sparkle shower','cat-party'=>'Cat party','none'=>'No effect'] as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($pers['card_reveal']??'gentle',$k,false).'>'.esc_html($v).'</option>';echo '</select></label><button class="btn" name="manage_action" value="save">Save card settings</button>';}else echo '<p>You can correct the recipient email and resend the card notification.</p><button class="btn" name="manage_action" value="resend">Save &amp; resend email</button> <button class="btn secondary" name="manage_action" value="save">Save email only</button>';echo '</form></section></main></body></html>';exit;}
 private static function deliver_card_entry($order,$index,$force=false){
  if(get_post_meta($order,'_ssshop_order_status',true)!=='paid')return new WP_Error('unpaid_order','The order has not been paid.');
  $lock='ssshop_delivery_lock_'.absint($order);
  if(!add_option($lock,time(),'','no')){if((int)get_option($lock)<time()-300)delete_option($lock);return new WP_Error('delivery_busy','This card is already being processed.');}
  try{$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(!is_array($tokens)||empty($tokens[$index]))return new WP_Error('missing_card','Card not found.');$e=$tokens[$index];if(!empty($e['sent_at'])&&!$force)return true;$pers=$e['personalisation']??[];$to=sanitize_email($pers['recipient_email']??'');if(!$to)return new WP_Error('missing_email','Recipient email is missing.');$date=$pers['delivery_date']??'';$time=$pers['delivery_time']??'09:00';if(!$force&&self::delivery_timestamp($pers)>time())return false;$sender=sanitize_text_field($pers['sender_name']??'Someone');$recipient=sanitize_text_field($pers['recipient_name']??'there');$pid=absint($e['product_id']??0);$repl=['{sender_name}'=>$sender,'{recipient_name}'=>$recipient,'{product}'=>$pid?get_the_title($pid):'e-card','{delivery_date}'=>self::display_delivery($date,$time)];$subject=strtr(get_option('ssshop_email_subject','You have a rescue e-card from {sender_name}!'),$repl);$heading=strtr(get_option('ssshop_email_heading','You have a rescue e-card!'),$repl);$intro=nl2br(esc_html(strtr(get_option('ssshop_email_intro','{sender_name} has sent you something special. Open your card using the button below.'),$repl)));$url=self::card_url($e['token']);$body='<div style="background:#f7f2f8;padding:35px 15px;font-family:Arial,sans-serif;color:#252525"><div style="max-width:600px;margin:auto;background:#fff;border-radius:16px;padding:35px;text-align:center"><div style="font-size:50px">💌</div><h1 style="color:#48105f">'.esc_html($heading).'</h1><p style="font-size:16px;line-height:1.6">'.$intro.'</p><p style="margin:30px 0"><a href="'.esc_url($url).'" style="display:inline-block;background:#48105f;color:#fff;text-decoration:none;font-weight:bold;padding:14px 24px;border-radius:999px">Open your card</a></p><p style="font-size:13px;color:#666">This e-card helped support cats in need.<br>Sent with love and made paw-sible by Rescue. 🐾</p></div></div>';$reply=(($pers['share_buyer_email']??'no')==='yes'&&is_email($pers['buyer_email']??''))?$pers['buyer_email']:self::default_no_reply();$ok=self::send_shop_email($to,$subject,$body,$reply);$tokens[$index]['last_attempt_at']=current_time('mysql',true);if($ok){$now=current_time('mysql',true);if(empty($tokens[$index]['sent_at']))$tokens[$index]['sent_at']=$now;if(empty($tokens[$index]['locked_at']))$tokens[$index]['locked_at']=$now;$tokens[$index]['delivery_status']='sent';}else{$tokens[$index]['delivery_status']='failed';}$tokens[$index]['attempts']=(int)($tokens[$index]['attempts']??0)+1;update_post_meta($order,'_ssshop_card_tokens',$tokens);return $ok?true:new WP_Error('mail_failed','The email could not be handed to the configured mail service.');}finally{delete_option($lock);}
 }

 public static function process_due_deliveries() {
  // Process all paid orders in bounded batches, including older scheduled cards.
  self::cleanup_card_assets();$page=1;
  do{
   $orders=get_posts(['post_type'=>self::ORDER_TYPE,'post_status'=>'publish','posts_per_page'=>100,'paged'=>$page++,'orderby'=>'ID','order'=>'ASC','meta_key'=>'_ssshop_order_status','meta_value'=>'paid','fields'=>'ids']);
   foreach($orders as $order){if(!get_post_meta($order,'_ssshop_confirmation_sent',true))self::send_order_confirmation($order);$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(!is_array($tokens))continue;foreach($tokens as $index=>$entry){$due=self::delivery_timestamp($entry['personalisation']??[]);if(empty($entry['sent_at'])&&$due&&$due<=time())self::deliver_card_entry($order,$index);}}
  }while(count($orders)===100);
 }

 public static function ajax_order_status(){$order=absint($_POST['order']??0);$session=sanitize_text_field(wp_unslash($_POST['session_id']??''));if(!$order||!$session||get_post_meta($order,'_ssshop_stripe_session',true)!==$session)wp_send_json_error(['message'=>'Order could not be verified.'],403);$status=get_post_meta($order,'_ssshop_order_status',true);wp_send_json_success(['status'=>$status,'paid'=>$status==='paid']);}
