 public static function render_order_delivery($post){$tokens=get_post_meta($post->ID,'_ssshop_card_tokens',true);if(!is_array($tokens)||!$tokens){echo '<p>No e-cards are attached to this order.</p>';return;}$confirm_url=wp_nonce_url(admin_url('admin-post.php?action=ssshop_resend_confirmation&order='.$post->ID),'ssshop_resend_confirmation_'.$post->ID);echo '<p><a class="button" href="'.esc_url($confirm_url).'">Resend buyer confirmation email</a></p>';foreach($tokens as $i=>$e){$x=$e['personalisation']??[];$status=$e['delivery_status']??(!empty($e['sent_at'])?'sent':'scheduled');echo '<div style="padding:16px 0;border-bottom:1px solid #ddd"><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ssshop_update_card"><input type="hidden" name="order" value="'.absint($post->ID).'"><input type="hidden" name="card" value="'.absint($i).'">'.wp_nonce_field('ssshop_update_card_'.$post->ID.'_'.$i,'_wpnonce',true,false).'<p><strong>'.esc_html($x['recipient_name']??'Recipient').'</strong><br>Status: <strong>'.esc_html(ucfirst($status)).'</strong>';if(!empty($e['sent_at']))echo '<br>Sent: '.esc_html($e['sent_at']).' UTC';echo '</p><p><label>Recipient email<br><input type="email" name="recipient_email" value="'.esc_attr($x['recipient_email']??'').'" style="min-width:320px" required></label></p><p><label>Delivery date <input type="date" name="delivery_date" value="'.esc_attr($x['delivery_date']??'').'"></label> <label>Time <input type="time" name="delivery_time" value="'.esc_attr($x['delivery_time']??'09:00').'"></label></p><p><button class="button" type="submit">Save details</button> <a class="button" target="_blank" rel="noopener" href="'.esc_url(self::card_url($e['token'])).'">Preview card</a> ';$url=wp_nonce_url(admin_url('admin-post.php?action=ssshop_send_card_now&order='.$post->ID.'&card='.$i),'ssshop_send_card_'.$post->ID.'_'.$i);echo '<a class="button button-primary" href="'.esc_url($url).'" onclick="return confirm(\'Send/resend this card email now?\')">'.(!empty($e['sent_at'])?'Resend email':'Send now').'</a></p></form>';if(!empty($e['audit'])&&is_array($e['audit'])){echo '<details><summary>Change history</summary><ul>';foreach(array_reverse(array_slice($e['audit'],-10)) as $a)echo '<li>'.esc_html(($a['at']??'').' UTC · '.($a['actor']??'').' · '.($a['action']??'').' · '.($a['detail']??'')).'</li>';echo '</ul></details>';}echo '</div>';}}
 public static function admin_update_card(){if(!current_user_can('manage_options'))wp_die('Access denied.');$order=absint($_POST['order']??0);$card=absint($_POST['card']??0);check_admin_referer('ssshop_update_card_'.$order.'_'.$card);$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(!is_array($tokens)||!isset($tokens[$card]))wp_die('Card not found.');$email=sanitize_email(wp_unslash($_POST['recipient_email']??''));if(!$email||!is_email($email))wp_die('A valid recipient email is required.');$entry=$tokens[$card];$p=$entry['personalisation']??[];$p['recipient_email']=$email;$date=sanitize_text_field(wp_unslash($_POST['delivery_date']??''));$time=sanitize_text_field(wp_unslash($_POST['delivery_time']??''));if($date&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$p['delivery_date']=$date;if($time&&preg_match('/^\d{2}:\d{2}$/',$time))$p['delivery_time']=$time;$p['delivery_timestamp']=self::delivery_timestamp($p);$entry['personalisation']=$p;if(empty($entry['sent_at']))$entry['delivery_status']='scheduled';self::audit_card($entry,'admin_updated','Email '.$email.'; delivery '.($p['delivery_date']??'').' '.($p['delivery_time']??''),'admin:'.wp_get_current_user()->user_login);$tokens[$card]=$entry;update_post_meta($order,'_ssshop_card_tokens',$tokens);wp_safe_redirect(add_query_arg('ssshop_delivery','updated',get_edit_post_link($order,'')));exit;}
 public static function admin_resend_confirmation(){if(!current_user_can('manage_options'))wp_die('Access denied.');$order=absint($_GET['order']??0);check_admin_referer('ssshop_resend_confirmation_'.$order);delete_post_meta($order,'_ssshop_confirmation_sent');self::send_order_confirmation($order,true);wp_safe_redirect(add_query_arg('ssshop_delivery','confirmation',get_edit_post_link($order,'')));exit;}
 public static function delivery_admin_notice(){if(empty($_GET['ssshop_delivery']))return;$s=sanitize_key($_GET['ssshop_delivery']);$messages=['sent'=>'E-card email sent successfully.','updated'=>'E-card details updated.','confirmation'=>'Order confirmation email resent.','failed'=>'The e-card could not be sent. Check the site email configuration and try again.'];echo '<div class="notice '.($s==='failed'?'notice-error':'notice-success').' is-dismissible"><p>'.esc_html($messages[$s]??'E-card updated.').'</p></div>';}
 public static function admin_send_card_now(){if(!current_user_can('manage_options'))wp_die('Access denied.');$order=absint($_GET['order']??0);$card=absint($_GET['card']??0);check_admin_referer('ssshop_send_card_'.$order.'_'.$card);$tokens=get_post_meta($order,'_ssshop_card_tokens',true);if(is_array($tokens)&&isset($tokens[$card])){self::audit_card($tokens[$card],'admin_send_email','Manual send/resend','admin:'.wp_get_current_user()->user_login);update_post_meta($order,'_ssshop_card_tokens',$tokens);}$r=self::deliver_card_entry($order,$card,true);$url=get_edit_post_link($order,'');$url=add_query_arg('ssshop_delivery',is_wp_error($r)?'failed':'sent',$url);wp_safe_redirect($url);exit;}
 private static function group_url($token){return add_query_arg('ssshop_group',rawurlencode($token),home_url('/'));}
