 private static function group_owner($token) {
  $cookie='ssshop_gc_'.substr(hash('sha256',$token),0,16);$raw=$_COOKIE[$cookie]??'';$id='';
  if(is_string($raw)&&preg_match('/^(c-[a-f0-9]{32})\.([a-f0-9]{64})$/',wp_unslash($raw),$matches)){
   $signature=hash_hmac('sha256',$token.'|'.$matches[1],wp_salt('auth'));
   if(hash_equals($signature,$matches[2]))$id=$matches[1];
  }
  if(!$id){$id='c-'.bin2hex(random_bytes(16));$value=$id.'.'.hash_hmac('sha256',$token.'|'.$id,wp_salt('auth'));setcookie($cookie,$value,['expires'=>time()+180*DAY_IN_SECONDS,'path'=>COOKIEPATH?:'/','secure'=>is_ssl(),'httponly'=>true,'samesite'=>'Lax']);$_COOKIE[$cookie]=$value;}
  return $id;
 }

 private static function group_blocks($blocks,$owner,$name,$prefix='From'){$out=[];foreach(array_slice(is_array($blocks)?$blocks:[],0,20) as $b){if(!is_array($b))continue;$b=array_filter($b,'is_scalar');$t=sanitize_key($b['type']??'text');$w=max($t==='text'?15:8,min($t==='text'?95:90,(float)($b['w']??($t==='text'?55:18))));$h=max(8,min(90,(float)($b['h']??20)));$base=['id'=>sanitize_text_field($b['id']??''),'type'=>$t,'owner_id'=>$owner,'x'=>max($w/2,min(100-$w/2,(float)($b['x']??50))),'y'=>max($h/2,min(100-$h/2,(float)($b['y']??50))),'w'=>$w,'h'=>$h,'rotation'=>max($t==='text'?-15:-180,min($t==='text'?15:180,(float)($b['rotation']??0)))];if($t==='sticker'){$s=(string)($b['sticker']??'🐾');if(!in_array($s,['🐾','🐱','😺','😻','❤️','💜','🎈','🎉','🎂','🎁','⭐','🌈','🌸','✨'],true))$s='🐾';$base['sticker']=$s;$out[]=$base;}elseif($t==='image'){$a=sanitize_text_field($b['asset_token']??'');if(preg_match('/^[a-f0-9]{64}$/',$a)&&self::card_asset_meta($a)){$base['asset_token']=$a;$base['url']=self::card_asset_url($a);$out[]=$base;}}elseif($t==='text'){$text=mb_substr(sanitize_textarea_field($b['text']??''),0,1000);if(trim($text)==='')continue;$font=sanitize_key($b['font']??'sans');if(!in_array($font,['sans','serif','handwriting','rounded','elegant','typewriter','playful','bold-display','soft-script','modern','paw-print','cat-scratch','whiskers','bouncy','storybook','party','marker','bubble'],true))$font='sans';$base+=['text'=>$text,'from_name'=>$name,'from_prefix'=>mb_substr(sanitize_text_field((string)($b['from_prefix']??$prefix)),0,40),'show_from'=>!empty($b['show_from']),'font'=>$font,'font_size'=>max(12,min(72,(int)($b['font_size']??20))),'colour'=>sanitize_hex_color($b['colour']??'#48105f')?:'#48105f','bold'=>!empty($b['bold']),'italic'=>!empty($b['italic']),'underline'=>!empty($b['underline']),'align'=>in_array(($b['align']??''),['left','center','right'],true)?$b['align']:'left'];$out[]=$base;}}return$out;}
