(()=>{const intro=document.getElementById("intro"),viewer=document.getElementById("viewer"),cover=document.querySelector(".closed-view"),book=document.getElementById("book"),back=document.getElementById("backView"),pages=[...document.querySelectorAll(".card-page")],count=document.getElementById("pageCount"),prev=document.getElementById("prev"),next=document.getElementById("next"),blank=document.getElementById("blankFacing"),printBook=document.getElementById("printBook"),box=document.getElementById("particles"),symbol='.wp_json_encode($particle).';let current=0,celebrated=false;
