function goNext(){if(isMobileCard()&&state>0&&state<finalState()){let pageIndex=state-1;if(pageIndex+1<insideCount){state++;renderState();return}state=finalState();renderState();return}if(state<finalState()){state++;renderState()}}
function goPrev(){if(isMobileCard()&&state===finalState()&&insideCount){state=insideCount;renderState();return}if(state>0){state--;renderState()}}
function celebrate(){if(celebrated||!symbol||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;celebrated=true;const effect='.wp_json_encode($reveal).';box.classList.add("fx-"+effect);if(effect==="fireworks"){const bursts=[{x:25,y:31,c:"#ff4f87",delay:0},{x:52,y:22,c:"#ffd54a",delay:.32},{x:76,y:36,c:"#7c5cff",delay:.62},{x:39,y:50,c:"#42d6c6",delay:.92},{x:68,y:56,c:"#ff8a3d",delay:1.18}];bursts.forEach((burst,bi)=>{const sparks=20;for(let n=0;n<sparks;n++){const e=document.createElement("span");e.className="particle";const a=Math.PI*2*n/sparks+(bi%2?.08:0),dist=70+Math.random()*105;e.style.left=burst.x+"%";e.style.top=burst.y+"%";e.style.setProperty("--dx",Math.cos(a)*dist+"px");e.style.setProperty("--dy",Math.sin(a)*dist+"px");e.style.setProperty("--spark",burst.c);e.style.animationDelay=(burst.delay+Math.random()*.12)+"s";box.appendChild(e)}});return}const advanced=effect==="celebration",count=advanced?44:(effect==="balloons"?20:30);for(let n=0;n<count;n++){const e=document.createElement("span");e.className="particle";e.textContent=effect==="celebration"?(["🎊","🎉","✨","⭐"][n%4]):effect==="cat-party"?(["😺","🐾","🎉","😻"][n%4]):symbol;if(advanced){const a=(Math.PI*2*n/count)+(Math.random()*.18),dist=100+Math.random()*340;e.style.setProperty("--dx",Math.cos(a)*dist+"px");e.style.setProperty("--dy",Math.sin(a)*dist+"px");e.style.setProperty("--rot",(Math.random()*720-360)+"deg");e.style.left=(45+Math.random()*10)+"%";e.style.top=(42+Math.random()*16)+"%"}else e.style.left=(Math.random()*100)+"%";e.style.animationDelay=(Math.random()*.9)+"s";box.appendChild(e)}}
document.getElementById("reveal").onclick=()=>{intro.classList.add("gone");viewer.classList.add("ready");viewer.setAttribute("aria-hidden","false");state=0;renderState();celebrate()};
prev.onclick=goPrev;next.onclick=goNext;
function buildPrintBook(){printBook.innerHTML="";const add=(node,extra="")=>{const c=node.cloneNode(true);c.removeAttribute("id");c.removeAttribute("hidden");c.classList.remove("active","spread-left","spread-right");c.classList.add("print-sheet");if(extra)c.classList.add(extra);printBook.appendChild(c)};add(cover,"print-cover");pages.forEach(p=>add(p,"print-card-page"));add(back,"print-back")}
window.addEventListener("beforeprint",buildPrintBook);window.addEventListener("resize",renderState);document.getElementById("print").onclick=()=>{buildPrintBook();window.print()};document.getElementById("download").onclick=()=>{const u=new URL(location.href);u.searchParams.set("ssshop_print","1");const w=window.open(u.toString(),"_blank");if(!w){buildPrintBook();window.print();return}w.addEventListener("load",()=>setTimeout(()=>w.print(),400),{once:true})};renderState();
if(new URLSearchParams(location.search).get("ssshop_print")==="1"){intro.classList.add("gone");viewer.classList.add("ready");renderState();buildPrintBook();setTimeout(()=>window.print(),500)}
})();
</script></body></html>';exit;}}status_header(404);exit('Card not found.');}
 public static function columns($c){$c['ssshop_price']='Price';$c['ssshop_format']='Format';$c['ssshop_visibility']='Visibility';return$c;} public static function column_value($col,$id){if($col==='ssshop_price')echo '£'.esc_html(number_format(((int)get_post_meta($id,'_ssshop_price_pence',true))/100,2));if($col==='ssshop_format')echo esc_html(ucfirst(get_post_meta($id,'_ssshop_type',true)?:'digital'));if($col==='ssshop_visibility')echo esc_html(ucfirst(get_post_meta($id,'_ssshop_visibility',true)?:'catalogue'));}
 public static function order_columns($c){return['cb'=>$c['cb'],'title'=>'Order','ssshop_status'=>'Status','ssshop_total'=>'Total','ssshop_customer'=>'Customer','date'=>'Created'];} public static function order_column_value($col,$id){if($col==='ssshop_status')echo esc_html(ucwords(str_replace('_',' ',get_post_meta($id,'_ssshop_order_status',true)?:'pending')));if($col==='ssshop_total')echo '£'.esc_html(number_format(((int)get_post_meta($id,'_ssshop_order_total',true))/100,2));if($col==='ssshop_customer')echo esc_html(get_post_meta($id,'_ssshop_customer_email',true)?:'—');}
}
